// ─── Lesson "Deep Dive" sections ─────────────────────────────────────────────
// One extra, self-contained section appended to every lesson to add depth. Each
// entry carries the section's heading + body (paragraphs split on \n\n) in all
// six languages. These are merged in at the render boundary by
// getTranslatedLesson, so they show consistently everywhere a lesson renders and
// require no edits to the large lesson-data or split-translation files.
//
// English (en) is always present; other languages fall back to en when missing,
// exactly like the rest of the content pipeline.
import type { Language } from './translations';

export interface DeepDiveSection { heading: string; body: string; }
export type DeepDive = { en: DeepDiveSection } & Partial<Record<Language, DeepDiveSection>>;

export const LESSON_DEEP_DIVES: Record<string, DeepDive> = {
  // ══════════════════════════ ANCIENT ══════════════════════════
  'ancient-01': {
    en: { heading: "The Indus Valley: A Third River Civilization",
      body: "While Mesopotamia and Egypt flourished, a third great civilization arose along the Indus River in what is now Pakistan and northwest India. The Harappan civilization (c.2600–1900 BCE) built remarkable planned cities such as Harappa and Mohenjo-daro, laid out on precise grids with baked-brick houses, covered drains, and the world's first urban sanitation systems.\n\nThe Harappans standardized weights and measures, traded with Mesopotamia by sea, and produced a script that has never been deciphered. Unlike their contemporaries, they left no palaces, royal tombs, or monuments to war — hinting at a society organized in a strikingly different way. Around 1900 BCE the cities were gradually abandoned, likely as shifting rivers and a changing climate undermined their farmland." },
    es: { heading: "El valle del Indo: una tercera civilización fluvial",
      body: "Mientras Mesopotamia y Egipto florecían, una tercera gran civilización surgió a lo largo del río Indo, en lo que hoy son Pakistán y el noroeste de la India. La civilización harappa (c.2600–1900 a.C.) construyó ciudades notablemente planificadas, como Harappa y Mohenjo-daro, trazadas en cuadrículas precisas, con casas de ladrillo cocido, alcantarillas cubiertas y los primeros sistemas urbanos de saneamiento del mundo.\n\nLos harappas estandarizaron pesos y medidas, comerciaron por mar con Mesopotamia y crearon una escritura que nunca ha sido descifrada. A diferencia de sus contemporáneos, no dejaron palacios, tumbas reales ni monumentos a la guerra, lo que sugiere una sociedad organizada de un modo muy distinto. Hacia el 1900 a.C. las ciudades fueron abandonadas poco a poco, probablemente porque el cambio de los ríos y del clima arruinó sus tierras de cultivo." },
    ru: { heading: "Долина Инда: третья речная цивилизация",
      body: "Пока процветали Месопотамия и Египет, третья великая цивилизация возникла в долине реки Инд — на территории современного Пакистана и северо-западной Индии. Хараппская цивилизация (ок. 2600–1900 гг. до н.э.) строила удивительно спланированные города, такие как Хараппа и Мохенджо-Даро, с чёткой сеткой улиц, домами из обожжённого кирпича, крытыми стоками и первыми в мире городскими системами канализации.\n\nХараппцы ввели единые меры веса и длины, торговали с Месопотамией по морю и создали письменность, которая до сих пор не расшифрована. В отличие от современников, они не оставили ни дворцов, ни царских гробниц, ни памятников войнам — что указывает на совершенно иначе устроенное общество. Около 1900 г. до н.э. города постепенно опустели, вероятно, из-за того что смещение рек и изменение климата подорвали их земледелие." },
    mk: { heading: "Долината на Инд: трета речна цивилизација",
      body: "Додека Месопотамија и Египет цветаа, трета голема цивилизација се појави долж реката Инд, на територијата на денешен Пакистан и северозападна Индија. Харапската цивилизација (о. 2600–1900 п.н.е.) градела извонредно испланирани градови како Харапа и Мохенџо-Даро, поставени во прецизни мрежи, со куќи од печена тула, покриени одводи и првите урбани системи за санитарна хигиена во светот.\n\nХарапците вовеле стандардни мерки за тежина и должина, тргувале со Месопотамија по море и создале писмо што досега не е дешифрирано. За разлика од своите современици, не оставиле ниту палати, ниту кралски гробници, ниту споменици на војна — што укажува на општество организирано на впечатливо поинаков начин. Околу 1900 п.н.е. градовите постепено биле напуштени, најверојатно бидејќи поместувањето на реките и климатските промени го уништиле нивното земјоделство." },
    de: { heading: "Das Industal: eine dritte Stromkultur",
      body: "Während Mesopotamien und Ägypten blühten, entstand am Indus im heutigen Pakistan und Nordwestindien eine dritte große Zivilisation. Die Harappa-Kultur (ca. 2600–1900 v. Chr.) errichtete bemerkenswert geplante Städte wie Harappa und Mohenjo-daro, angelegt in präzisen Rastern, mit Häusern aus gebranntem Ziegel, überdachten Abwasserkanälen und den ersten städtischen Sanitärsystemen der Welt.\n\nDie Harappaner vereinheitlichten Maße und Gewichte, trieben über das Meer Handel mit Mesopotamien und schufen eine bis heute nicht entzifferte Schrift. Anders als ihre Zeitgenossen hinterließen sie weder Paläste noch Königsgräber oder Kriegsdenkmäler — ein Hinweis auf eine ganz anders organisierte Gesellschaft. Um 1900 v. Chr. wurden die Städte allmählich verlassen, wahrscheinlich weil sich verlagernde Flüsse und ein Klimawandel ihre Felder zerstörten." },
    fr: { heading: "La vallée de l'Indus : une troisième civilisation fluviale",
      body: "Tandis que la Mésopotamie et l'Égypte prospéraient, une troisième grande civilisation naquit le long de l'Indus, dans l'actuel Pakistan et le nord-ouest de l'Inde. La civilisation harappéenne (v. 2600–1900 av. J.-C.) bâtit des villes remarquablement planifiées, comme Harappa et Mohenjo-daro, tracées selon des grilles précises, avec des maisons en brique cuite, des égouts couverts et les premiers systèmes urbains d'assainissement au monde.\n\nLes Harappéens normalisèrent poids et mesures, commercèrent par mer avec la Mésopotamie et créèrent une écriture jamais déchiffrée. Contrairement à leurs contemporains, ils ne laissèrent ni palais, ni tombes royales, ni monuments guerriers — signe d'une société organisée de façon très différente. Vers 1900 av. J.-C., les villes furent peu à peu abandonnées, sans doute parce que le déplacement des rivières et un changement climatique ruinèrent leurs terres agricoles." },
  },
  'ancient-02': {
    en: { heading: "The Birth of Theatre",
      body: "Classical Athens gave the world theatre. Drama grew out of religious festivals honoring Dionysus, the god of wine and ecstasy, where choruses sang and danced. In the fifth century BCE, playwrights transformed these rituals into a new art form performed in vast open-air theatres carved into hillsides, some seating over 15,000 spectators with acoustics so fine that a whisper on stage carried to the last row.\n\nThree great tragedians — Aeschylus, Sophocles, and Euripides — probed fate, justice, and human suffering in plays still staged today, from Oedipus Rex to Antigone. Aristophanes perfected comedy, mocking politicians and philosophers without mercy. Greek audiences believed that watching tragedy produced catharsis, a purifying release of pity and fear that left citizens wiser and more compassionate." },
    es: { heading: "El nacimiento del teatro",
      body: "La Atenas clásica dio al mundo el teatro. El drama surgió de las fiestas religiosas en honor a Dioniso, dios del vino y el éxtasis, donde los coros cantaban y bailaban. En el siglo V a.C., los dramaturgos transformaron esos rituales en un nuevo arte representado en enormes teatros al aire libre excavados en las laderas, algunos con capacidad para más de 15.000 espectadores y una acústica tan perfecta que un susurro en el escenario llegaba a la última fila.\n\nTres grandes trágicos —Esquilo, Sófocles y Eurípides— exploraron el destino, la justicia y el sufrimiento humano en obras que aún se representan hoy, desde Edipo rey hasta Antígona. Aristófanes perfeccionó la comedia, burlándose sin piedad de políticos y filósofos. El público griego creía que ver una tragedia producía catarsis, una liberación purificadora de la compasión y el miedo que dejaba a los ciudadanos más sabios y humanos." },
    ru: { heading: "Рождение театра",
      body: "Классические Афины подарили миру театр. Драма выросла из религиозных праздников в честь Диониса, бога вина и экстаза, где хоры пели и танцевали. В V веке до н.э. драматурги превратили эти обряды в новое искусство, которое разыгрывалось в огромных театрах под открытым небом, вырубленных в склонах холмов; некоторые вмещали более 15 000 зрителей, а их акустика была так хороша, что шёпот на сцене доносился до последнего ряда.\n\nТри великих трагика — Эсхил, Софокл и Еврипид — исследовали судьбу, справедливость и человеческое страдание в пьесах, которые ставят и сегодня, от «Царя Эдипа» до «Антигоны». Аристофан довёл до совершенства комедию, безжалостно высмеивая политиков и философов. Греки верили, что созерцание трагедии вызывает катарсис — очищающее освобождение от жалости и страха, делавшее граждан мудрее и человечнее." },
    mk: { heading: "Раѓањето на театарот",
      body: "Класична Атина му го подари театарот на светот. Драмата израсна од религиозните празници во чест на Дионис, богот на виното и екстазата, каде што хоровите пееја и играа. Во петтиот век п.н.е. драматурзите ги преобразија тие обреди во нова уметност изведувана во огромни театри на отворено, вклепани во падините на ридовите; некои примале над 15.000 гледачи, а акустиката им била толку добра што шепот на сцената стигнувал до последниот ред.\n\nТројца големи трагичари — Есхил, Софокле и Еврипид — ги истражуваа судбината, правдата и човечкото страдање во дела што и денес се играат, од „Цар Едип“ до „Антигона“. Аристофан ја усоврши комедијата, безмилосно исмевајќи ги политичарите и филозофите. Грците верувале дека гледањето трагедија предизвикува катарза — прочистувачко ослободување од сожалување и страв што ги оставало граѓаните помудри и почовечни." },
    de: { heading: "Die Geburt des Theaters",
      body: "Das klassische Athen schenkte der Welt das Theater. Das Drama erwuchs aus religiösen Festen zu Ehren des Dionysos, des Gottes des Weins und der Ekstase, bei denen Chöre sangen und tanzten. Im fünften Jahrhundert v. Chr. verwandelten Dichter diese Rituale in eine neue Kunstform, aufgeführt in gewaltigen Freilufttheatern, die in Hänge gehauen waren; manche fassten über 15.000 Zuschauer, mit einer Akustik, die selbst ein Flüstern auf der Bühne bis in die letzte Reihe trug.\n\nDrei große Tragiker — Aischylos, Sophokles und Euripides — ergründeten Schicksal, Gerechtigkeit und menschliches Leid in Stücken, die bis heute gespielt werden, von König Ödipus bis Antigone. Aristophanes vervollkommnete die Komödie und verspottete Politiker und Philosophen schonungslos. Die Griechen glaubten, das Betrachten einer Tragödie bewirke Katharsis — eine reinigende Befreiung von Mitleid und Furcht, die die Bürger weiser und mitfühlender zurückließ." },
    fr: { heading: "La naissance du théâtre",
      body: "L'Athènes classique offrit le théâtre au monde. Le drame naquit des fêtes religieuses en l'honneur de Dionysos, dieu du vin et de l'extase, où des chœurs chantaient et dansaient. Au Ve siècle av. J.-C., les auteurs transformèrent ces rites en un art nouveau, joué dans d'immenses théâtres de plein air taillés à flanc de colline ; certains pouvaient accueillir plus de 15 000 spectateurs, avec une acoustique si fine qu'un murmure sur scène parvenait au dernier rang.\n\nTrois grands tragiques — Eschyle, Sophocle et Euripide — sondèrent le destin, la justice et la souffrance humaine dans des pièces encore jouées aujourd'hui, d'Œdipe roi à Antigone. Aristophane perfectionna la comédie, raillant sans pitié politiciens et philosophes. Les Grecs croyaient que regarder une tragédie produisait la catharsis, une libération purificatrice de la pitié et de la peur qui rendait les citoyens plus sages et plus humains." },
  },
  'ancient-03': {
    en: { heading: "The Legions: Engine of Empire",
      body: "Rome's empire was built and held by the most formidable military machine of the ancient world: the legion. Each legion of roughly 5,000 men was divided into cohorts and centuries, drilled into a discipline so relentless that the Jewish historian Josephus called their exercises 'bloodless battles and their battles bloody exercises.' Around 107 BCE the general Marius opened the ranks to landless citizens, turning the army into a profession and giving soldiers a stake in their commanders' success.\n\nBeyond fighting, legionaries were builders. On campaign they raised a fortified camp every night; in peacetime they paved roads, dug aqueducts, and threw bridges across rivers. Twenty-five years of service earned a soldier Roman citizenship or a plot of land, spreading Roman culture to every frontier. Yet the army's loyalty to its generals rather than the state also made it the maker — and destroyer — of emperors." },
    es: { heading: "Las legiones: motor del imperio",
      body: "El imperio de Roma fue construido y sostenido por la máquina militar más formidable del mundo antiguo: la legión. Cada legión, de unos 5.000 hombres, se dividía en cohortes y centurias, adiestradas con una disciplina tan implacable que el historiador judío Josefo llamó a sus ejercicios 'batallas sin sangre, y a sus batallas ejercicios sangrientos'. Hacia el 107 a.C. el general Mario abrió las filas a los ciudadanos sin tierra, convirtiendo el ejército en una profesión y dando a los soldados un interés en el éxito de sus jefes.\n\nAdemás de combatir, los legionarios eran constructores. En campaña levantaban un campamento fortificado cada noche; en tiempos de paz pavimentaban calzadas, excavaban acueductos y tendían puentes sobre los ríos. Veinticinco años de servicio daban al soldado la ciudadanía romana o una parcela de tierra, difundiendo la cultura romana por cada frontera. Pero la lealtad del ejército a sus generales, más que al Estado, lo convirtió también en el hacedor —y destructor— de emperadores." },
    ru: { heading: "Легионы: двигатель империи",
      body: "Империю Рима создала и удерживала самая грозная военная машина древнего мира — легион. Каждый легион примерно из 5000 человек делился на когорты и центурии, вымуштрованные с такой беспощадной дисциплиной, что иудейский историк Иосиф Флавий называл их учения «бескровными сражениями, а сражения — кровавыми учениями». Около 107 г. до н.э. полководец Марий открыл ряды безземельным гражданам, превратив армию в профессию и дав солдатам заинтересованность в успехе своих командиров.\n\nЛегионеры были не только воинами, но и строителями. В походе они каждую ночь возводили укреплённый лагерь; в мирное время мостили дороги, копали акведуки и наводили мосты через реки. Двадцать пять лет службы приносили солдату римское гражданство или надел земли, разнося римскую культуру по всем рубежам. Но верность армии своим полководцам, а не государству, сделала её и создателем, и погубителем императоров." },
    mk: { heading: "Легиите: моторот на империјата",
      body: "Римската империја беше изградена и одржувана од најстрашната воена машина на античкиот свет — легијата. Секоја легија од околу 5.000 луѓе се делеше на кохорти и центурии, извежбани со толку немилосрдна дисциплина што еврејскиот историчар Јосиф Флавиј нивните вежби ги нарече „бескрвни битки, а битките — крвави вежби“. Околу 107 п.н.е. војсководецот Мариј ги отвори редовите за безземјашките граѓани, претворајќи ја војската во професија и давајќи им на војниците интерес за успехот на своите команданти.\n\nОсвен што се бореа, легионерите беа и градители. На поход секоја ноќ подигаа утврден логор; во мирнодопски услови поплочуваа патишта, копаа аквадукти и фрлаа мостови преку реките. Дваесет и пет години служба му носеа на војникот римско државјанство или парче земја, ширејќи ја римската култура по секоја граница. Но верноста на војската кон своите војсководци, а не кон државата, ја направи и создавач и уништувач на императорите." },
    de: { heading: "Die Legionen: Motor des Reiches",
      body: "Roms Reich wurde von der furchterregendsten Militärmaschine der Antike errichtet und gehalten: der Legion. Jede Legion von rund 5.000 Mann war in Kohorten und Zenturien gegliedert und mit einer so unerbittlichen Disziplin gedrillt, dass der jüdische Geschichtsschreiber Josephus ihre Übungen 'unblutige Schlachten und ihre Schlachten blutige Übungen' nannte. Um 107 v. Chr. öffnete der Feldherr Marius die Reihen für besitzlose Bürger und machte das Heer zum Beruf, sodass die Soldaten am Erfolg ihrer Feldherren beteiligt waren.\n\nDie Legionäre waren nicht nur Kämpfer, sondern auch Baumeister. Auf dem Feldzug errichteten sie jede Nacht ein befestigtes Lager; in Friedenszeiten pflasterten sie Straßen, gruben Aquädukte und schlugen Brücken über Flüsse. Fünfundzwanzig Dienstjahre brachten dem Soldaten das römische Bürgerrecht oder ein Stück Land und trugen die römische Kultur an jede Grenze. Doch die Treue des Heeres zu seinen Feldherren statt zum Staat machte es auch zum Macher — und Zerstörer — von Kaisern." },
    fr: { heading: "Les légions : moteur de l'empire",
      body: "L'empire de Rome fut bâti et maintenu par la plus redoutable machine militaire du monde antique : la légion. Chaque légion d'environ 5 000 hommes se divisait en cohortes et centuries, entraînées avec une discipline si implacable que l'historien juif Flavius Josèphe qualifiait leurs exercices de 'batailles sans effusion de sang, et leurs batailles d'exercices sanglants'. Vers 107 av. J.-C., le général Marius ouvrit les rangs aux citoyens sans terre, faisant de l'armée un métier et donnant aux soldats un intérêt dans le succès de leurs chefs.\n\nAu-delà du combat, les légionnaires étaient bâtisseurs. En campagne, ils dressaient chaque nuit un camp fortifié ; en temps de paix, ils pavaient des routes, creusaient des aqueducs et jetaient des ponts sur les rivières. Vingt-cinq ans de service valaient au soldat la citoyenneté romaine ou un lopin de terre, répandant la culture romaine sur chaque frontière. Mais la fidélité de l'armée à ses généraux plutôt qu'à l'État en fit aussi le faiseur — et le destructeur — d'empereurs." },
  },
  'ancient-04': {
    en: { heading: "Nomads of the Steppe",
      body: "The great settled empires of Persia, India, and China all shared one restless neighbor: the nomads of the Eurasian steppe. Mounted herders such as the Scythians and the Xiongnu mastered the horse and the composite bow, becoming the finest cavalry of the ancient world. Able to appear suddenly and vanish across grasslands that stretched thousands of kilometers, they raided rich farmland and taxed the caravans of the Silk Road.\n\nTheir pressure shaped history. China built and rebuilt the Great Wall to hold back the Xiongnu, whose confederation rivaled the Han in power. Persia's King Cyrus the Great died fighting steppe nomads. Far from being mere destroyers, these horse peoples carried goods, technologies, and ideas between distant civilizations, knitting the ancient world together even as they threatened it." },
    es: { heading: "Los nómadas de la estepa",
      body: "Los grandes imperios sedentarios de Persia, India y China compartían un vecino inquieto: los nómadas de la estepa euroasiática. Pastores a caballo como los escitas y los xiongnu dominaron el caballo y el arco compuesto, y se convirtieron en la mejor caballería del mundo antiguo. Capaces de aparecer de pronto y esfumarse por praderas que se extendían miles de kilómetros, saqueaban las ricas tierras de labor y cobraban tributo a las caravanas de la Ruta de la Seda.\n\nSu presión moldeó la historia. China construyó y reconstruyó la Gran Muralla para contener a los xiongnu, cuya confederación rivalizaba en poder con la dinastía Han. El rey persa Ciro el Grande murió luchando contra nómadas de la estepa. Lejos de ser simples destructores, estos pueblos jinetes transportaban mercancías, tecnologías e ideas entre civilizaciones lejanas, entrelazando el mundo antiguo aun cuando lo amenazaban." },
    ru: { heading: "Кочевники степи",
      body: "У великих оседлых империй Персии, Индии и Китая был один беспокойный сосед — кочевники евразийской степи. Конные скотоводы, такие как скифы и хунну, в совершенстве владели конём и составным луком и стали лучшей конницей древнего мира. Способные внезапно появиться и раствориться в травяных просторах, тянувшихся на тысячи километров, они разоряли богатые пашни и облагали данью караваны Шёлкового пути.\n\nИх натиск определял ход истории. Китай строил и перестраивал Великую стену, чтобы сдержать хунну, чей союз соперничал по мощи с империей Хань. Персидский царь Кир Великий погиб в войне со степными кочевниками. Отнюдь не будучи лишь разрушителями, эти конные народы переносили товары, технологии и идеи между далёкими цивилизациями, связывая древний мир, даже когда угрожали ему." },
    mk: { heading: "Номадите на степата",
      body: "Големите населени империи на Персија, Индија и Кина имаа еден немирен сосед: номадите на евроазиската степа. Коњанички сточари како Скитите и Ксионгну (Хунну) го совладаа коњот и сложениот лак и станаа најдобрата коњица на античкиот свет. Способни одненадеж да се појават и да исчезнат низ тревниците што се протегаа илјадници километри, ги пустошеа плодните ниви и им наплаќаа данок на караваните на Патот на свилата.\n\nНивниот притисок ја обликуваше историјата. Кина го градеше и повторно го градеше Кинескиот ѕид за да ги задржи Ксионгну, чија конфедерација се натпреваруваше со Хан по моќ. Персискиот крал Кир Велики загина борејќи се против степски номади. Далеку од тоа да бидат само уништувачи, овие коњанички народи пренесуваа стоки, технологии и идеи меѓу далечни цивилизации, поврзувајќи го античкиот свет дури и додека го загрозуваа." },
    de: { heading: "Nomaden der Steppe",
      body: "Die großen sesshaften Reiche Persiens, Indiens und Chinas hatten alle einen ruhelosen Nachbarn: die Nomaden der eurasischen Steppe. Berittene Hirten wie die Skythen und die Xiongnu beherrschten Pferd und Kompositbogen und wurden zur besten Reiterei der Antike. Fähig, plötzlich aufzutauchen und über tausende Kilometer weites Grasland wieder zu verschwinden, plünderten sie fruchtbares Ackerland und besteuerten die Karawanen der Seidenstraße.\n\nIhr Druck formte die Geschichte. China baute die Große Mauer immer wieder, um die Xiongnu abzuwehren, deren Bund es an Macht mit den Han aufnahm. Der persische König Kyros der Große fiel im Kampf gegen Steppennomaden. Weit davon entfernt, bloße Zerstörer zu sein, trugen diese Reitervölker Waren, Techniken und Ideen zwischen fernen Kulturen hin und her und verknüpften so die antike Welt, noch während sie sie bedrohten." },
    fr: { heading: "Les nomades de la steppe",
      body: "Les grands empires sédentaires de Perse, d'Inde et de Chine partageaient tous un voisin turbulent : les nomades de la steppe eurasienne. Des éleveurs cavaliers comme les Scythes et les Xiongnu maîtrisèrent le cheval et l'arc composite et devinrent la meilleure cavalerie du monde antique. Capables de surgir soudain et de s'évanouir dans des prairies longues de milliers de kilomètres, ils pillaient les riches terres cultivées et taxaient les caravanes de la route de la Soie.\n\nLeur pression façonna l'histoire. La Chine bâtit et rebâtit la Grande Muraille pour contenir les Xiongnu, dont la confédération rivalisait de puissance avec les Han. Le roi perse Cyrus le Grand mourut en combattant des nomades des steppes. Loin d'être de simples destructeurs, ces peuples cavaliers transportaient marchandises, techniques et idées entre des civilisations lointaines, tissant le monde antique alors même qu'ils le menaçaient." },
  },
  'ancient-05': {
    en: { heading: "Akhenaten and the Amarna Revolution",
      body: "Around 1350 BCE, the pharaoh Amenhotep IV launched the most radical religious revolution in Egyptian history. He renamed himself Akhenaten, abolished the worship of Egypt's traditional gods, and declared that only the Aten — the life-giving disk of the sun — was divine. He built a brand-new capital, Amarna, in the desert and closed the wealthy temples of Amun, shattering a priesthood that had rivaled the throne.\n\nAkhenaten's revolution transformed Egyptian art, which suddenly portrayed the royal family with intimate, almost tender realism, alongside his famous queen Nefertiti. But the experiment did not outlive him. His young successor — the boy-king Tutankhamun — restored the old gods and moved the court back to Thebes. Priests erased Akhenaten's name from monuments, and his heretic city crumbled into the sand, forgotten until archaeologists uncovered it more than three thousand years later." },
    es: { heading: "Akhenatón y la revolución de Amarna",
      body: "Hacia el 1350 a.C., el faraón Amenhotep IV lanzó la revolución religiosa más radical de la historia egipcia. Se rebautizó como Akhenatón, abolió el culto a los dioses tradicionales de Egipto y declaró que solo el Atón —el disco solar que da la vida— era divino. Construyó una capital totalmente nueva, Amarna, en el desierto, y cerró los ricos templos de Amón, quebrando a un clero que había rivalizado con el trono.\n\nLa revolución de Akhenatón transformó el arte egipcio, que de pronto retrató a la familia real con un realismo íntimo, casi tierno, junto a su célebre reina Nefertiti. Pero el experimento no le sobrevivió. Su joven sucesor —el niño-rey Tutankamón— restauró a los viejos dioses y devolvió la corte a Tebas. Los sacerdotes borraron el nombre de Akhenatón de los monumentos, y su ciudad herética se deshizo en la arena, olvidada hasta que los arqueólogos la descubrieron más de tres mil años después." },
    ru: { heading: "Эхнатон и Амарнская революция",
      body: "Около 1350 г. до н.э. фараон Аменхотеп IV начал самую радикальную религиозную революцию в истории Египта. Он переименовал себя в Эхнатона, отменил почитание традиционных египетских богов и объявил, что божественен лишь Атон — дарующий жизнь солнечный диск. Он построил совершенно новую столицу, Амарну, посреди пустыни и закрыл богатые храмы Амона, сокрушив жречество, которое соперничало с троном.\n\nРеволюция Эхнатона преобразила египетское искусство, которое вдруг стало изображать царскую семью с интимным, почти нежным реализмом, рядом с его знаменитой царицей Нефертити. Но эксперимент не пережил своего создателя. Его юный преемник — мальчик-царь Тутанхамон — восстановил старых богов и вернул двор в Фивы. Жрецы стёрли имя Эхнатона с памятников, а его еретический город рассыпался в песок и был забыт, пока археологи не раскопали его более трёх тысяч лет спустя." },
    mk: { heading: "Ехнатон и револуцијата во Амарна",
      body: "Околу 1350 п.н.е. фараонот Аменхотеп IV ја започна најрадикалната верска револуција во египетската историја. Се преименува во Ехнатон, го укина обожавањето на традиционалните египетски богови и објави дека само Атон — животодавниот сончев диск — е божествен. Изгради сосема нова престолнина, Амарна, во пустината и ги затвори богатите храмови на Амон, кршејќи го свештенството што му конкурираше на престолот.\n\nРеволуцијата на Ехнатон ја преобрази египетската уметност, која одеднаш ја прикажуваше кралската фамилија со интимен, речиси нежен реализам, заедно со неговата прочуена кралица Нефертити. Но експериментот не го надживеа неговиот творец. Неговиот млад наследник — детето-крал Тутанкамон — ги врати старите богови и го премести дворот назад во Теба. Свештениците го избришаа името на Ехнатон од спомениците, а неговиот еретички град се распадна во песокот, заборавен сè додека археолозите не го откопаа повеќе од три илјади години подоцна." },
    de: { heading: "Echnaton und die Amarna-Revolution",
      body: "Um 1350 v. Chr. entfachte der Pharao Amenophis IV. die radikalste religiöse Revolution der ägyptischen Geschichte. Er nannte sich Echnaton, schaffte die Verehrung der traditionellen Götter Ägyptens ab und erklärte allein den Aton — die lebenspendende Sonnenscheibe — für göttlich. Er baute mitten in der Wüste eine völlig neue Hauptstadt, Amarna, und schloss die reichen Amun-Tempel, womit er eine Priesterschaft brach, die mit dem Thron rivalisiert hatte.\n\nEchnatons Revolution wandelte die ägyptische Kunst, die plötzlich die königliche Familie mit inniger, fast zärtlicher Naturtreue zeigte, an seiner Seite die berühmte Königin Nofretete. Doch das Experiment überlebte ihn nicht. Sein junger Nachfolger — der Kindkönig Tutanchamun — stellte die alten Götter wieder her und verlegte den Hof zurück nach Theben. Priester tilgten Echnatons Namen von den Denkmälern, und seine Ketzerstadt zerfiel im Sand, vergessen, bis Archäologen sie mehr als dreitausend Jahre später freilegten." },
    fr: { heading: "Akhénaton et la révolution d'Amarna",
      body: "Vers 1350 av. J.-C., le pharaon Amenhotep IV déclencha la révolution religieuse la plus radicale de l'histoire égyptienne. Il se rebaptisa Akhénaton, abolit le culte des dieux traditionnels de l'Égypte et proclama que seul l'Aton — le disque solaire qui donne la vie — était divin. Il bâtit une capitale entièrement neuve, Amarna, en plein désert, et ferma les riches temples d'Amon, brisant un clergé qui avait rivalisé avec le trône.\n\nLa révolution d'Akhénaton transforma l'art égyptien, qui représenta soudain la famille royale avec un réalisme intime, presque tendre, aux côtés de sa célèbre reine Néfertiti. Mais l'expérience ne lui survécut pas. Son jeune successeur — le roi-enfant Toutânkhamon — rétablit les anciens dieux et ramena la cour à Thèbes. Les prêtres effacèrent le nom d'Akhénaton des monuments, et sa cité hérétique s'effrita dans le sable, oubliée jusqu'à ce que les archéologues la mettent au jour plus de trois mille ans plus tard." },
  },
  'ancient-06': {
    en: { heading: "Carthage: The Phoenician West",
      body: "As Phoenician traders pushed west across the Mediterranean, they planted colonies far from their Levantine homeland. The greatest of these, Carthage, was founded near modern Tunis around 814 BCE according to tradition, and grew into a maritime superpower in its own right. From its double harbor, Carthaginian fleets controlled the western sea lanes, mined silver in Spain, and traded for tin as far as the coasts of Britain.\n\nCarthage carried Phoenician culture — the gods Baal and Tanit, the alphabet, and a genius for commerce — deep into the western world. Its wealth eventually brought it into a titanic collision with Rome in the Punic Wars, a rivalry that would end in Carthage's destruction in 146 BCE. Yet for centuries Carthage had shown that the Phoenician model of seaborne trade could build an empire without the vast conquering armies of the East." },
    es: { heading: "Cartago: el Occidente fenicio",
      body: "A medida que los comerciantes fenicios se adentraban hacia el oeste del Mediterráneo, fundaron colonias lejos de su patria levantina. La mayor de ellas, Cartago, fue fundada cerca de la actual Túnez hacia el 814 a.C. según la tradición, y llegó a ser una superpotencia marítima por derecho propio. Desde su doble puerto, las flotas cartaginesas controlaban las rutas marítimas occidentales, extraían plata en Hispania y comerciaban estaño hasta las costas de Britania.\n\nCartago llevó la cultura fenicia —los dioses Baal y Tanit, el alfabeto y un genio para el comercio— hasta lo más profundo del mundo occidental. Su riqueza acabó llevándola a un choque titánico con Roma en las Guerras Púnicas, una rivalidad que terminaría con la destrucción de Cartago en el 146 a.C. Pero durante siglos Cartago había demostrado que el modelo fenicio de comercio marítimo podía construir un imperio sin los enormes ejércitos conquistadores de Oriente." },
    ru: { heading: "Карфаген: финикийский Запад",
      body: "По мере того как финикийские купцы продвигались на запад по Средиземноморью, они основывали колонии вдали от своей левантийской родины. Крупнейшая из них, Карфаген, по преданию был основан близ современного Туниса около 814 г. до н.э. и сам вырос в морскую сверхдержаву. Из своей двойной гавани карфагенские флоты держали западные морские пути, добывали серебро в Испании и торговали оловом до самых берегов Британии.\n\nКарфаген донёс финикийскую культуру — богов Ваала и Танит, алфавит и торговый гений — вглубь западного мира. Его богатство в конце концов привело к титаническому столкновению с Римом в Пунических войнах — соперничеству, которое завершилось разрушением Карфагена в 146 г. до н.э. Но на протяжении веков Карфаген доказывал, что финикийская модель морской торговли способна создать империю без огромных завоевательных армий Востока." },
    mk: { heading: "Картагина: финикискиот Запад",
      body: "Како што финикиските трговци навлегуваа на запад низ Медитеранот, засадуваа колонии далеку од својата левантска татковина. Најголемата од нив, Картагина, според преданието била основана близу денешен Тунис околу 814 п.н.е. и самата прераснала во поморска суперсила. Од своето двојно пристаниште, картагинските флоти ги контролираа западните морски патишта, копаа сребро во Шпанија и тргуваа со калај дури до бреговите на Британија.\n\nКартагина ја пренесе финикиската култура — боговите Ваал и Танит, азбуката и генијот за трговија — длабоко во западниот свет. Нејзиното богатство на крајот ја доведе до титански судир со Рим во Пунските војни — ривалство што ќе заврши со уништувањето на Картагина во 146 п.н.е. Но со векови Картагина покажуваше дека финикискиот модел на поморска трговија може да изгради империја без огромните освојувачки војски на Истокот." },
    de: { heading: "Karthago: der phönizische Westen",
      body: "Als phönizische Händler nach Westen über das Mittelmeer vorstießen, gründeten sie Kolonien fern ihrer levantinischen Heimat. Die größte davon, Karthago, wurde der Überlieferung nach um 814 v. Chr. nahe dem heutigen Tunis gegründet und wuchs selbst zu einer Seemacht heran. Von ihrem Doppelhafen aus beherrschten karthagische Flotten die westlichen Seewege, förderten Silber in Spanien und handelten Zinn bis zu den Küsten Britanniens.\n\nKarthago trug die phönizische Kultur — die Götter Baal und Tanit, das Alphabet und einen Sinn für Handel — tief in die westliche Welt. Sein Reichtum führte es schließlich in einen titanischen Zusammenstoß mit Rom in den Punischen Kriegen, einer Rivalität, die 146 v. Chr. mit der Zerstörung Karthagos endete. Doch jahrhundertelang hatte Karthago gezeigt, dass das phönizische Modell des Seehandels ein Reich errichten konnte, ohne die gewaltigen Eroberungsheere des Ostens." },
    fr: { heading: "Carthage : l'Occident phénicien",
      body: "À mesure que les marchands phéniciens progressaient vers l'ouest de la Méditerranée, ils fondèrent des colonies loin de leur patrie levantine. La plus grande, Carthage, fut fondée près de l'actuelle Tunis vers 814 av. J.-C. selon la tradition, et devint elle-même une superpuissance maritime. Depuis son double port, les flottes carthaginoises contrôlaient les routes maritimes occidentales, exploitaient l'argent d'Espagne et échangeaient l'étain jusqu'aux côtes de la Bretagne.\n\nCarthage porta la culture phénicienne — les dieux Baal et Tanit, l'alphabet et un génie du commerce — jusqu'au cœur du monde occidental. Sa richesse finit par la précipiter dans un choc titanesque avec Rome lors des guerres puniques, une rivalité qui s'acheva par la destruction de Carthage en 146 av. J.-C. Mais pendant des siècles, Carthage avait montré que le modèle phénicien du commerce maritime pouvait bâtir un empire sans les vastes armées conquérantes de l'Orient." },
  },
  'ancient-07': {
    en: { heading: "Philip's War Machine: The Macedonian Phalanx",
      body: "Alexander the Great conquered the world with an army perfected by his father, King Philip II. Philip reforged the Macedonian infantry into the phalanx, a bristling block of soldiers wielding the sarissa — a pike up to six meters long. Rank upon rank lowered their pikes, presenting the enemy with an impenetrable hedge of iron points that no frontal charge could break.\n\nBut the phalanx was only the anvil. Philip paired it with the hammer: the Companion Cavalry, elite horsemen who charged the enemy's flank at the decisive moment. This 'hammer and anvil' tactic — pinning the foe with pikes while cavalry shattered their side — made the Macedonian army the deadliest of its age. Alexander wielded it with genius at Issus and Gaugamela, toppling the vast Persian Empire with a force a fraction of its size." },
    es: { heading: "La máquina de guerra de Filipo: la falange macedonia",
      body: "Alejandro Magno conquistó el mundo con un ejército perfeccionado por su padre, el rey Filipo II. Filipo reforjó la infantería macedonia en la falange, un bloque erizado de soldados que empuñaban la sarisa, una pica de hasta seis metros de largo. Fila tras fila bajaban sus picas, presentando al enemigo un seto impenetrable de puntas de hierro que ninguna carga frontal podía romper.\n\nPero la falange era solo el yunque. Filipo la combinó con el martillo: la Caballería de los Compañeros, jinetes de élite que cargaban contra el flanco enemigo en el momento decisivo. Esta táctica de 'martillo y yunque' —fijar al adversario con las picas mientras la caballería destrozaba su costado— convirtió al ejército macedonio en el más letal de su época. Alejandro la empleó con genialidad en Issos y Gaugamela, derribando el vasto Imperio persa con una fuerza mucho menor." },
    ru: { heading: "Военная машина Филиппа: македонская фаланга",
      body: "Александр Македонский покорил мир с армией, доведённой до совершенства его отцом, царём Филиппом II. Филипп перековал македонскую пехоту в фалангу — ощетинившийся строй воинов с сариссами, пиками длиной до шести метров. Ряд за рядом опускали свои пики, выставляя перед врагом непроницаемую изгородь железных наконечников, которую не могла пробить никакая лобовая атака.\n\nНо фаланга была лишь наковальней. Филипп соединил её с молотом — гетайрами, отборной конницей, которая в решающий миг обрушивалась на фланг врага. Эта тактика «молота и наковальни» — сковать противника пиками, пока конница крушит его бок, — сделала македонскую армию самой смертоносной в своё время. Александр применял её с гениальностью при Иссе и Гавгамелах, сокрушив огромную Персидскую державу силами во много раз меньшими." },
    mk: { heading: "Воената машина на Филип: македонската фаланга",
      body: "Александар Македонски го освои светот со војска усовршена од неговиот татко, кралот Филип II. Филип ја претвори македонската пешадија во фаланга — наежен блок војници што ја носеа сарисата, копје долго до шест метри. Ред по ред ги спуштаа копјата, покажувајќи му на непријателот непробоен плот од железни врвови што ниеден фронтален јуриш не можеше да го скрши.\n\nНо фалангата беше само наковалната. Филип ја спои со чеканот: Хетајрите, елитни коњаници што во одлучувачкиот миг удираа по крилото на непријателот. Оваа тактика на „чекан и наковална“ — да се закове противникот со копјата додека коњицата му го крши бокот — ја направи македонската војска најсмртоносна во своето време. Александар ја применуваше со гениј кај Ис и Гавгамела, соборувајќи ја огромната Персиска империја со сила многу помала од нејзината." },
    de: { heading: "Philipps Kriegsmaschine: die makedonische Phalanx",
      body: "Alexander der Große eroberte die Welt mit einem Heer, das sein Vater, König Philipp II., vervollkommnet hatte. Philipp formte die makedonische Infanterie zur Phalanx um, einem starrenden Block von Soldaten mit der Sarisse, einer bis zu sechs Meter langen Pike. Reihe um Reihe senkten sie ihre Piken und boten dem Feind eine undurchdringliche Hecke eiserner Spitzen, die kein Frontalangriff brechen konnte.\n\nDoch die Phalanx war nur der Amboss. Philipp verband sie mit dem Hammer: der Hetairenreiterei, edlen Reitern, die im entscheidenden Augenblick die Flanke des Feindes anfielen. Diese Taktik von 'Hammer und Amboss' — den Gegner mit Piken festnageln, während die Reiterei seine Seite zerschlug — machte das makedonische Heer zum tödlichsten seiner Zeit. Alexander führte sie mit Genie bei Issos und Gaugamela und stürzte das riesige Perserreich mit einer weit kleineren Streitmacht." },
    fr: { heading: "La machine de guerre de Philippe : la phalange macédonienne",
      body: "Alexandre le Grand conquit le monde avec une armée perfectionnée par son père, le roi Philippe II. Philippe refondit l'infanterie macédonienne en phalange, un bloc hérissé de soldats maniant la sarisse, une pique longue de six mètres. Rang après rang, ils abaissaient leurs piques, opposant à l'ennemi une haie impénétrable de pointes de fer qu'aucune charge frontale ne pouvait rompre.\n\nMais la phalange n'était que l'enclume. Philippe l'associa au marteau : la cavalerie des Compagnons, cavaliers d'élite qui chargeaient le flanc ennemi à l'instant décisif. Cette tactique du 'marteau et de l'enclume' — fixer l'adversaire avec les piques tandis que la cavalerie brisait son flanc — fit de l'armée macédonienne la plus meurtrière de son temps. Alexandre la manœuvra avec génie à Issos et à Gaugamèles, renversant le vaste Empire perse avec une force bien moindre." },
  },
  'ancient-08': {
    en: { heading: "Machines and Marvels: Hellenistic Science",
      body: "The Hellenistic age was one of the most inventive eras before the modern world. In the cosmopolitan cities founded after Alexander, Greek reasoning met the deep records of Babylon and Egypt, and the result was an explosion of science. Archimedes of Syracuse calculated pi, explained the lever and buoyancy, and built ingenious war machines. Ctesibius and Hero of Alexandria designed pumps, water clocks, and even a spinning sphere driven by steam.\n\nThe most astonishing survival is the Antikythera mechanism, a bronze device of more than thirty interlocking gears recovered from a shipwreck. It could track the movements of the sun, moon, and planets and forecast eclipses — an analog computer two thousand years ahead of anything comparable. Such marvels reveal a Hellenistic world probing nature with a precision and ambition that would not be matched again until the Renaissance." },
    es: { heading: "Máquinas y maravillas: la ciencia helenística",
      body: "La era helenística fue una de las más inventivas antes del mundo moderno. En las ciudades cosmopolitas fundadas tras Alejandro, el razonamiento griego se encontró con los profundos registros de Babilonia y Egipto, y el resultado fue una explosión de ciencia. Arquímedes de Siracusa calculó el número pi, explicó la palanca y la flotabilidad y construyó ingeniosas máquinas de guerra. Ctesibio y Herón de Alejandría diseñaron bombas, relojes de agua e incluso una esfera giratoria impulsada por vapor.\n\nEl hallazgo más asombroso es el mecanismo de Anticitera, un artefacto de bronce con más de treinta engranajes entrelazados rescatado de un naufragio. Podía seguir los movimientos del sol, la luna y los planetas y anticipar eclipses: una computadora analógica dos mil años por delante de cualquier cosa comparable. Tales maravillas revelan un mundo helenístico que sondeaba la naturaleza con una precisión y una ambición que no volverían a igualarse hasta el Renacimiento." },
    ru: { heading: "Машины и чудеса: эллинистическая наука",
      body: "Эллинистическая эпоха была одной из самых изобретательных до Нового времени. В космополитичных городах, основанных после Александра, греческое мышление встретилось с обширными записями Вавилона и Египта, и результатом стал взрыв науки. Архимед из Сиракуз вычислил число пи, объяснил рычаг и закон плавучести и построил хитроумные боевые машины. Ктесибий и Герон Александрийский создавали насосы, водяные часы и даже вращающийся шар, приводимый в движение паром.\n\nСамая поразительная находка — антикитерский механизм, бронзовое устройство из более чем тридцати сцепленных шестерён, поднятое с затонувшего корабля. Оно могло отслеживать движения Солнца, Луны и планет и рассчитывать затмения — аналоговый вычислитель, на две тысячи лет опередивший всё сопоставимое. Такие чудеса открывают эллинистический мир, исследовавший природу с точностью и размахом, которые повторятся лишь в эпоху Возрождения." },
    mk: { heading: "Машини и чуда: хеленистичката наука",
      body: "Хеленистичката ера беше една од најизумителните пред современиот свет. Во космополитските градови основани по Александар, грчкото расудување се сретна со длабоките записи на Вавилон и Египет, и резултатот беше експлозија на наука. Архимед од Сиракуза го пресмета бројот пи, ги објасни полугата и потисокот и изгради досетливи воени машини. Ктесибиј и Херон Александриски создаваа пумпи, водени часовници, па дури и вртлива сфера погонувана од пареа.\n\nНајзачудувачкиот наод е механизмот од Антикитера, бронзена направа од повеќе од триесет заплеткани запчаници извадена од бродолом. Можеше да ги следи движењата на Сонцето, Месечината и планетите и да пресметува затемнувања — аналоген сметач две илјади години пред сè споредливо. Ваквите чуда откриваат хеленистички свет што ја испитуваше природата со прецизност и амбиција што повторно ќе се достигнат дури во ренесансата." },
    de: { heading: "Maschinen und Wunder: hellenistische Wissenschaft",
      body: "Das hellenistische Zeitalter zählte zu den erfinderischsten vor der Neuzeit. In den weltoffenen Städten, die nach Alexander entstanden, traf griechisches Denken auf die reichen Aufzeichnungen Babylons und Ägyptens, und das Ergebnis war ein Aufbruch der Wissenschaft. Archimedes von Syrakus berechnete die Zahl Pi, erklärte Hebel und Auftrieb und baute sinnreiche Kriegsmaschinen. Ktesibios und Heron von Alexandria entwarfen Pumpen, Wasseruhren und sogar eine dampfgetriebene, sich drehende Kugel.\n\nDer erstaunlichste Fund ist der Mechanismus von Antikythera, ein Bronzegerät aus über dreißig ineinandergreifenden Zahnrädern, geborgen aus einem Schiffswrack. Es konnte die Bewegungen von Sonne, Mond und Planeten verfolgen und Finsternisse berechnen — ein Analogrechner, der allem Vergleichbaren um zweitausend Jahre voraus war. Solche Wunder zeigen eine hellenistische Welt, die die Natur mit einer Genauigkeit und einem Ehrgeiz erforschte, die erst in der Renaissance wieder erreicht wurden." },
    fr: { heading: "Machines et merveilles : la science hellénistique",
      body: "L'âge hellénistique fut l'un des plus inventifs avant le monde moderne. Dans les villes cosmopolites fondées après Alexandre, la raison grecque rencontra les archives profondes de Babylone et d'Égypte, et il en résulta une explosion scientifique. Archimède de Syracuse calcula le nombre pi, expliqua le levier et la poussée d'Archimède et bâtit d'ingénieuses machines de guerre. Ctésibios et Héron d'Alexandrie conçurent des pompes, des horloges à eau et même une sphère tournante mue par la vapeur.\n\nLe vestige le plus stupéfiant est la machine d'Anticythère, un appareil de bronze de plus de trente engrenages imbriqués, repêché d'une épave. Elle pouvait suivre les mouvements du soleil, de la lune et des planètes et annoncer les éclipses — un calculateur analogique en avance de deux mille ans sur tout ce qui lui était comparable. De telles merveilles révèlent un monde hellénistique sondant la nature avec une précision et une ambition qui ne seraient égalées qu'à la Renaissance." },
  },
  'ancient-09': {
    en: { heading: "Zoroaster and the Religion of Fire",
      body: "The Persian Empire was bound together not only by roads and satraps but by one of the world's oldest revealed religions: Zoroastrianism. Its prophet, Zarathustra (Zoroaster), taught that the universe is a battleground between Ahura Mazda, the god of light and truth, and the forces of the lie and darkness. Every person, by choosing good thoughts, good words, and good deeds, joins the cosmic struggle on the side of order.\n\nThe Achaemenid kings honored Ahura Mazda and tended sacred fires that symbolized his purity — fires kept burning in temples for generations. Zoroastrian ideas — a single supreme god, a final judgment, heaven and hell, and a coming savior — would echo through Judaism, Christianity, and Islam. Though few Zoroastrians remain today, their faith shaped the moral imagination of half the world." },
    es: { heading: "Zoroastro y la religión del fuego",
      body: "El Imperio persa estaba unido no solo por caminos y sátrapas, sino por una de las religiones reveladas más antiguas del mundo: el zoroastrismo. Su profeta, Zaratustra (Zoroastro), enseñó que el universo es un campo de batalla entre Ahura Mazda, el dios de la luz y la verdad, y las fuerzas de la mentira y la oscuridad. Cada persona, al elegir buenos pensamientos, buenas palabras y buenas obras, se une a la lucha cósmica del lado del orden.\n\nLos reyes aqueménidas honraban a Ahura Mazda y cuidaban fuegos sagrados que simbolizaban su pureza, fuegos mantenidos encendidos en los templos durante generaciones. Las ideas zoroástricas —un único dios supremo, un juicio final, el cielo y el infierno, y un salvador venidero— resonarían en el judaísmo, el cristianismo y el islam. Aunque hoy quedan pocos zoroastrianos, su fe moldeó la imaginación moral de medio mundo." },
    ru: { heading: "Заратустра и религия огня",
      body: "Персидскую державу связывали воедино не только дороги и сатрапы, но и одна из древнейших религий откровения — зороастризм. Его пророк Заратустра (Зороастр) учил, что вселенная есть поле битвы между Ахура-Маздой, богом света и истины, и силами лжи и тьмы. Каждый человек, избирая благие мысли, благие слова и благие дела, встаёт в космической борьбе на сторону порядка.\n\nАхеменидские цари чтили Ахура-Мазду и поддерживали священные огни, символ его чистоты, — огни, горевшие в храмах из поколения в поколение. Зороастрийские идеи — единый верховный бог, окончательный суд, рай и ад, грядущий спаситель — отзовутся в иудаизме, христианстве и исламе. Хотя зороастрийцев ныне немного, их вера сформировала нравственное воображение половины мира." },
    mk: { heading: "Заратустра и религијата на огнот",
      body: "Персиската империја беше поврзана не само со патишта и сатрапи, туку и со една од најстарите откриени религии на светот: зороастризмот. Неговиот пророк Заратустра (Зороастер) учеше дека вселената е бојно поле меѓу Ахура Мазда, богот на светлината и вистината, и силите на лагата и темнината. Секој човек, избирајќи добри мисли, добри зборови и добри дела, се приклучува на космичката борба на страната на редот.\n\nАхеменидските кралеви го почитуваа Ахура Мазда и одржуваа свети огнови што ја симболизираа неговата чистота — огнови што горееја во храмовите со поколенија. Зороастриските идеи — единствен врховен бог, конечен суд, рај и пекол, и иден спасител — ќе одекнат низ јудаизмот, христијанството и исламот. Иако денес останале малку зороастријци, нивната вера ја обликуваше моралната имагинација на половина свет." },
    de: { heading: "Zarathustra und die Religion des Feuers",
      body: "Das Perserreich wurde nicht nur durch Straßen und Satrapen zusammengehalten, sondern durch eine der ältesten Offenbarungsreligionen der Welt: den Zoroastrismus. Sein Prophet Zarathustra (Zoroaster) lehrte, das Universum sei ein Schlachtfeld zwischen Ahura Mazda, dem Gott des Lichts und der Wahrheit, und den Mächten der Lüge und Finsternis. Jeder Mensch tritt, indem er gute Gedanken, gute Worte und gute Taten wählt, im kosmischen Kampf auf die Seite der Ordnung.\n\nDie Achämenidenkönige ehrten Ahura Mazda und pflegten heilige Feuer, die seine Reinheit versinnbildlichten — Feuer, die über Generationen in Tempeln brannten. Zoroastrische Vorstellungen — ein einziger höchster Gott, ein Jüngstes Gericht, Himmel und Hölle und ein kommender Erlöser — sollten in Judentum, Christentum und Islam nachhallen. Auch wenn heute nur wenige Zoroastrier leben, prägte ihr Glaube die moralische Vorstellungswelt der halben Menschheit." },
    fr: { heading: "Zoroastre et la religion du feu",
      body: "L'Empire perse était uni non seulement par des routes et des satrapes, mais par l'une des plus anciennes religions révélées du monde : le zoroastrisme. Son prophète, Zarathoustra (Zoroastre), enseignait que l'univers est un champ de bataille entre Ahura Mazda, le dieu de la lumière et de la vérité, et les forces du mensonge et des ténèbres. Chaque être humain, en choisissant les bonnes pensées, les bonnes paroles et les bonnes actions, rejoint le combat cosmique du côté de l'ordre.\n\nLes rois achéménides honoraient Ahura Mazda et entretenaient des feux sacrés symbolisant sa pureté — des feux maintenus allumés dans les temples pendant des générations. Les idées zoroastriennes — un dieu suprême unique, un jugement dernier, le paradis et l'enfer, et un sauveur à venir — résonneraient dans le judaïsme, le christianisme et l'islam. Bien que peu de zoroastriens subsistent aujourd'hui, leur foi façonna l'imaginaire moral de la moitié du monde." },
  },

  // ══════════════════════════ MIDDLE AGES ══════════════════════════
  'medieval-01': {
    en: { heading: "Monasteries: Islands of Learning",
      body: "As Roman order dissolved, Christian monasteries became the quiet strongholds of learning in Western Europe. Following the Rule of Saint Benedict (c.529), monks lived by the motto 'pray and work,' dividing their days between worship, labor, and study. In their scriptoria, monks copied and recopied the Bible alongside the works of Roman authors, preserving texts that would otherwise have vanished.\n\nIrish monasteries were especially vital. Cut off from the collapse on the continent, Irish monks safeguarded Greek and Latin learning and then sailed out to re-found schools across Britain and Europe. Beyond books, monasteries cleared forests, drained marshes, brewed, farmed, and cared for the sick and the traveler. For centuries they were the single most important institution keeping literacy, agriculture, and charity alive." },
    es: { heading: "Islas de saber: los monasterios",
      body: "A medida que el orden romano se disolvía, los monasterios cristianos se convirtieron en los baluartes silenciosos del saber en Europa occidental. Siguiendo la Regla de San Benito (c.529), los monjes vivían bajo el lema 'ora y trabaja', repartiendo sus días entre el culto, el trabajo y el estudio. En sus scriptoria copiaban y recopiaban la Biblia junto a las obras de autores romanos, preservando textos que de otro modo se habrían perdido.\n\nLos monasterios irlandeses fueron especialmente vitales. Aislados del colapso del continente, los monjes irlandeses custodiaron el saber griego y latino y luego navegaron para refundar escuelas por toda Britania y Europa. Más allá de los libros, los monasterios talaban bosques, drenaban pantanos, elaboraban cerveza, cultivaban y cuidaban a los enfermos y a los viajeros. Durante siglos fueron la institución más importante para mantener vivas la alfabetización, la agricultura y la caridad." },
    ru: { heading: "Монастыри — острова учёности",
      body: "По мере распада римского порядка христианские монастыри стали тихими оплотами учёности в Западной Европе. Следуя Уставу святого Бенедикта (ок. 529), монахи жили по правилу «молись и трудись», деля дни между богослужением, трудом и учением. В своих скрипториях они переписывали и вновь переписывали Библию вместе с сочинениями римских авторов, сохраняя тексты, которые иначе исчезли бы.\n\nОсобенно важны были ирландские монастыри. Отрезанные от катастрофы на континенте, ирландские монахи сберегли греческую и латинскую учёность, а затем отплыли, чтобы заново основать школы по всей Британии и Европе. Помимо книг, монастыри расчищали леса, осушали болота, варили пиво, возделывали землю и заботились о больных и странниках. На протяжении веков они были важнейшим учреждением, поддерживавшим грамотность, земледелие и милосердие." },
    mk: { heading: "Манастирите — острови на учењето",
      body: "Како што римскиот поредок се распаѓаше, христијанските манастири станаа тивки тврдини на учењето во Западна Европа. Следејќи го Правилото на свети Бенедикт (о. 529), монасите живееја под мотото „моли се и работи“, делејќи ги деновите меѓу богослужение, труд и учење. Во своите скрипториуми ја препишуваа и повторно ја препишуваа Библијата заедно со делата на римските автори, зачувувајќи текстови што инаку би исчезнале.\n\nИрските манастири беа особено важни. Отсечени од распадот на континентот, ирските монаси го зачуваа грчкото и латинското знаење, а потоа отпловија за одново да основаат училишта низ Британија и Европа. Освен книгите, манастирите крчеа шуми, исушуваа мочуришта, вареа пиво, обработуваа земја и се грижеа за болните и патниците. Со векови беа најважната институција што ја одржуваше писменоста, земјоделството и милосрдието." },
    de: { heading: "Klöster: Inseln der Gelehrsamkeit",
      body: "Als die römische Ordnung zerfiel, wurden christliche Klöster zu den stillen Bollwerken der Gelehrsamkeit im Westen Europas. Nach der Regel des heiligen Benedikt (um 529) lebten die Mönche unter dem Leitwort 'bete und arbeite' und teilten ihre Tage zwischen Gottesdienst, Arbeit und Studium. In ihren Skriptorien schrieben sie die Bibel neben den Werken römischer Autoren immer wieder ab und bewahrten so Texte, die sonst verschwunden wären.\n\nDie irischen Klöster waren besonders wichtig. Vom Zusammenbruch auf dem Festland abgeschnitten, hüteten irische Mönche das griechische und lateinische Wissen und segelten dann aus, um Schulen in ganz Britannien und Europa neu zu gründen. Über Bücher hinaus rodeten Klöster Wälder, entwässerten Sümpfe, brauten, ackerten und pflegten Kranke und Reisende. Jahrhundertelang waren sie die wichtigste Einrichtung, die Bildung, Landwirtschaft und Nächstenliebe am Leben hielt." },
    fr: { heading: "Les monastères : îlots de savoir",
      body: "À mesure que l'ordre romain se dissolvait, les monastères chrétiens devinrent les bastions silencieux du savoir en Europe occidentale. Suivant la Règle de saint Benoît (v. 529), les moines vivaient selon la devise 'prie et travaille', partageant leurs journées entre le culte, le labeur et l'étude. Dans leurs scriptoria, ils copiaient et recopiaient la Bible aux côtés des œuvres des auteurs romains, préservant des textes qui, sans eux, auraient disparu.\n\nLes monastères irlandais furent particulièrement précieux. Coupés de l'effondrement du continent, les moines irlandais sauvegardèrent le savoir grec et latin, puis prirent la mer pour refonder des écoles à travers la Grande-Bretagne et l'Europe. Au-delà des livres, les monastères défrichaient les forêts, asséchaient les marais, brassaient, cultivaient et soignaient les malades et les voyageurs. Pendant des siècles, ils furent l'institution la plus essentielle au maintien de l'alphabétisation, de l'agriculture et de la charité." },
  },
  'medieval-02': {
    en: { heading: "Manzikert: The Battle That Sparked the Crusades",
      body: "The Crusades did not begin in a vacuum. In 1071, at Manzikert in eastern Anatolia, the Seljuk Turkish sultan Alp Arslan crushed the army of the Byzantine emperor Romanos IV and took him prisoner. The defeat tore open Byzantium's frontier, and Turkish nomads poured into Asia Minor — the empire's richest recruiting ground and breadbasket.\n\nDesperate, the Byzantine emperor Alexios I appealed to the Latin West for mercenaries to help recover his lost lands. Pope Urban II answered in 1095 with something far larger than the emperor expected: a call for an armed pilgrimage to free Jerusalem. Thus a single lost battle on a distant plateau set in motion two centuries of holy war between Christendom and Islam." },
    es: { heading: "Manzikert: la batalla que encendió las Cruzadas",
      body: "Las Cruzadas no surgieron de la nada. En 1071, en Manzikert, en el este de Anatolia, el sultán turco selyúcida Alp Arslan aplastó al ejército del emperador bizantino Romano IV y lo hizo prisionero. La derrota abrió de par en par la frontera de Bizancio, y los nómadas turcos se derramaron por Asia Menor, la región más rica en reclutas y el granero del imperio.\n\nDesesperado, el emperador bizantino Alejo I pidió a Occidente mercenarios para recuperar sus tierras perdidas. El papa Urbano II respondió en 1095 con algo mucho mayor de lo que el emperador esperaba: un llamamiento a una peregrinación armada para liberar Jerusalén. Así, una sola batalla perdida en una meseta lejana puso en marcha dos siglos de guerra santa entre la cristiandad y el islam." },
    ru: { heading: "Манцикерт: битва, зажёгшая Крестовые походы",
      body: "Крестовые походы возникли не на пустом месте. В 1071 году при Манцикерте в восточной Анатолии сельджукский султан Алп-Арслан разгромил войско византийского императора Романа IV и взял его в плен. Поражение распахнуло границу Византии, и турецкие кочевники хлынули в Малую Азию — богатейший источник рекрутов и житницу империи.\n\nВ отчаянии византийский император Алексей I обратился к латинскому Западу за наёмниками, чтобы вернуть утраченные земли. Папа Урбан II ответил в 1095 году чем-то куда большим, чем ожидал император, — призывом к вооружённому паломничеству ради освобождения Иерусалима. Так одна проигранная битва на далёком плоскогорье привела в движение два столетия священной войны между христианством и исламом." },
    mk: { heading: "Манцикерт: битката што ги запали Крстоносните војни",
      body: "Крстоносните војни не се појавија од ништо. Во 1071 година, кај Манцикерт во источна Анадолија, селџучкиот турски султан Алп Арслан ја смачка војската на византискиот император Роман IV и го зароби. Поразот ја отвори границата на Византија, и турските номади се излеаја во Мала Азија — најбогатиот извор на регрути и житницата на империјата.\n\nОчаен, византискиот император Алексиј I побара од латинскиот Запад платеници за да ги врати изгубените земји. Папата Урбан II одговори во 1095 година со нешто многу поголемо отколку што императорот очекуваше: повик за вооружено аџилак за ослободување на Ерусалим. Така една изгубена битка на далечна висорамнина стави во движење два века света војна меѓу христијанството и исламот." },
    de: { heading: "Manzikert: die Schlacht, die die Kreuzzüge entfachte",
      body: "Die Kreuzzüge entstanden nicht aus dem Nichts. 1071 zerschlug bei Manzikert im östlichen Anatolien der seldschukische Sultan Alp Arslan das Heer des byzantinischen Kaisers Romanos IV. und nahm ihn gefangen. Die Niederlage riss die Grenze von Byzanz auf, und türkische Nomaden strömten nach Kleinasien — das reichste Rekrutierungsgebiet und die Kornkammer des Reiches.\n\nVerzweifelt bat der byzantinische Kaiser Alexios I. den lateinischen Westen um Söldner, um seine verlorenen Länder zurückzugewinnen. Papst Urban II. antwortete 1095 mit weit mehr, als der Kaiser erwartet hatte: einem Aufruf zu einer bewaffneten Pilgerfahrt zur Befreiung Jerusalems. So setzte eine einzige verlorene Schlacht auf einem fernen Hochland zwei Jahrhunderte heiligen Krieges zwischen Christenheit und Islam in Gang." },
    fr: { heading: "Manzikert : la bataille qui alluma les croisades",
      body: "Les croisades ne surgirent pas de rien. En 1071, à Manzikert, dans l'est de l'Anatolie, le sultan turc seldjoukide Alp Arslan écrasa l'armée de l'empereur byzantin Romain IV et le fit prisonnier. La défaite ouvrit en grand la frontière de Byzance, et les nomades turcs déferlèrent sur l'Asie Mineure — le plus riche vivier de recrues et le grenier de l'empire.\n\nDésespéré, l'empereur byzantin Alexis Ier demanda à l'Occident latin des mercenaires pour reconquérir ses terres perdues. Le pape Urbain II répondit en 1095 par bien plus que ce que l'empereur attendait : un appel à un pèlerinage armé pour libérer Jérusalem. Ainsi une seule bataille perdue sur un plateau lointain mit en branle deux siècles de guerre sainte entre la chrétienté et l'islam." },
  },
  'medieval-03': {
    en: { heading: "Quarantine and the Birth of Public Health",
      body: "The Black Death killed perhaps a third of Europe, but it also forced the first organized public-health measures in the West. With no understanding of germs, city governments blamed 'bad air' — yet their responses were often shrewd. In 1377 the port of Ragusa (modern Dubrovnik) ordered arriving ships and travelers to wait in isolation before entering; Venice soon extended the wait to forty days, the quaranta giorni that gave us the word 'quarantine.'\n\nCities appointed health boards, isolated the sick in pest houses, and burned the belongings of the dead. These emergency measures hardened over time into permanent institutions of urban government. Long before anyone could see a bacterium, the plague taught Europe that disease could be tracked, contained, and fought by the state — a lesson at the root of modern public health." },
    es: { heading: "La cuarentena y el nacimiento de la salud pública",
      body: "La Peste Negra mató quizá a un tercio de Europa, pero también impuso las primeras medidas organizadas de salud pública en Occidente. Sin comprender los gérmenes, los gobiernos de las ciudades culpaban al 'aire malo', pero sus respuestas solían ser astutas. En 1377 el puerto de Ragusa (la actual Dubrovnik) ordenó que los barcos y viajeros que llegaban esperaran aislados antes de entrar; Venecia pronto amplió la espera a cuarenta días, los quaranta giorni que nos dieron la palabra 'cuarentena'.\n\nLas ciudades nombraron juntas de sanidad, aislaron a los enfermos en lazaretos y quemaron las pertenencias de los muertos. Estas medidas de emergencia se endurecieron con el tiempo hasta convertirse en instituciones permanentes del gobierno urbano. Mucho antes de que nadie pudiera ver una bacteria, la peste enseñó a Europa que la enfermedad podía rastrearse, contenerse y combatirse desde el Estado, una lección en la raíz de la salud pública moderna." },
    ru: { heading: "Карантин и рождение общественного здравоохранения",
      body: "Чёрная смерть унесла, возможно, треть Европы, но она же вынудила ввести первые организованные меры общественного здравоохранения на Западе. Не зная о микробах, городские власти винили «дурной воздух», однако их действия нередко были разумны. В 1377 году порт Рагуза (современный Дубровник) приказал прибывающим кораблям и путникам ждать в изоляции перед въездом; Венеция вскоре продлила ожидание до сорока дней — quaranta giorni, откуда и слово «карантин».\n\nГорода назначали санитарные советы, изолировали больных в чумных домах и сжигали имущество умерших. Эти чрезвычайные меры со временем затвердели в постоянные учреждения городского управления. Задолго до того как кто-либо смог увидеть бактерию, чума научила Европу, что болезнь можно отслеживать, сдерживать и побеждать силами государства, — урок, лежащий в основе современного здравоохранения." },
    mk: { heading: "Карантинот и раѓањето на јавното здравство",
      body: "Црната смрт усмрти можеби третина од Европа, но исто така ги наметна првите организирани мерки за јавно здравје на Западот. Без да знаат за микробите, градските власти го обвинуваа „лошиот воздух“, но нивните одговори често беа умни. Во 1377 година пристаништето Рагуза (денешен Дубровник) им нареди на пристигнатите бродови и патници да чекаат во изолација пред да влезат; Венеција набрзо го продолжи чекањето на четириесет дена — quaranta giorni, од каде што доаѓа зборот „карантин“.\n\nГрадовите именуваа здравствени одбори, ги изолираа болните во кужни куќи и ги палеа работите на мртвите. Овие итни мерки со текот на времето се стврднаа во трајни институции на градската власт. Долго пред некој да може да види бактерија, чумата ја научи Европа дека болеста може да се следи, да се задржи и да се победи од државата — лекција во коренот на современото јавно здравство." },
    de: { heading: "Quarantäne und die Geburt des öffentlichen Gesundheitswesens",
      body: "Der Schwarze Tod tötete vielleicht ein Drittel Europas, doch er erzwang auch die ersten organisierten Maßnahmen des öffentlichen Gesundheitswesens im Westen. Ohne Kenntnis von Krankheitserregern gaben die Stadtregierungen der 'schlechten Luft' die Schuld — ihre Reaktionen aber waren oft klug. 1377 ordnete der Hafen von Ragusa (dem heutigen Dubrovnik) an, dass ankommende Schiffe und Reisende vor dem Einlass in Isolation warten mussten; Venedig verlängerte die Wartezeit bald auf vierzig Tage, die quaranta giorni, die uns das Wort 'Quarantäne' schenkten.\n\nStädte setzten Gesundheitsräte ein, isolierten die Kranken in Pesthäusern und verbrannten die Habe der Toten. Diese Notmaßnahmen verfestigten sich mit der Zeit zu dauerhaften Einrichtungen der Stadtverwaltung. Lange bevor jemand ein Bakterium sehen konnte, lehrte die Pest Europa, dass Krankheit vom Staat verfolgt, eingedämmt und bekämpft werden kann — eine Lektion an der Wurzel des modernen Gesundheitswesens." },
    fr: { heading: "La quarantaine et la naissance de la santé publique",
      body: "La Peste noire tua peut-être un tiers de l'Europe, mais elle imposa aussi les premières mesures organisées de santé publique en Occident. Ignorant tout des germes, les gouvernements des villes accusaient le 'mauvais air' — pourtant leurs réponses étaient souvent judicieuses. En 1377, le port de Raguse (l'actuelle Dubrovnik) ordonna aux navires et voyageurs arrivants d'attendre en isolement avant d'entrer ; Venise porta bientôt l'attente à quarante jours, les quaranta giorni qui nous ont donné le mot 'quarantaine'.\n\nLes villes nommèrent des conseils de santé, isolèrent les malades dans des lazarets et brûlèrent les biens des morts. Ces mesures d'urgence se durcirent avec le temps en institutions permanentes du gouvernement urbain. Bien avant que quiconque pût voir une bactérie, la peste apprit à l'Europe que la maladie pouvait être suivie, contenue et combattue par l'État — une leçon à la racine de la santé publique moderne." },
  },
  'medieval-04': {
    en: { heading: "The Hanseatic League",
      body: "While Mediterranean trade enriched Italy, a very different commercial power rose in the cold north: the Hanseatic League. Beginning in the 13th century, German merchant towns led by Lübeck banded together to dominate trade across the Baltic and North Seas. At its height the League linked some 200 towns and ran trading posts, or kontors, from Novgorod in Russia to Bergen, Bruges, and London.\n\nThe Hansa dealt in the bulk goods of the north — grain, timber, furs, wax, and above all dried and salted fish that fed Catholic Europe on its many fast days. To protect its trade the League negotiated privileges, built warehouses, and even waged war on kings who threatened it. This merchant network showed that commerce alone, without a single ruler or army, could organize an economic empire spanning half a continent." },
    es: { heading: "La Liga Hanseática",
      body: "Mientras el comercio mediterráneo enriquecía a Italia, una potencia comercial muy distinta se alzaba en el frío norte: la Liga Hanseática. A partir del siglo XIII, ciudades mercantiles alemanas encabezadas por Lübeck se unieron para dominar el comercio del Báltico y el mar del Norte. En su apogeo, la Liga enlazaba unas 200 ciudades y gestionaba factorías, o kontors, desde Novgorod en Rusia hasta Bergen, Brujas y Londres.\n\nLa Hansa comerciaba con los productos a granel del norte —grano, madera, pieles, cera y, sobre todo, pescado seco y salado que alimentaba a la Europa católica en sus muchos días de ayuno—. Para proteger su comercio, la Liga negociaba privilegios, construía almacenes e incluso hacía la guerra a los reyes que la amenazaban. Esta red mercantil demostró que el comercio por sí solo, sin un único soberano ni ejército, podía organizar un imperio económico que abarcaba medio continente." },
    ru: { heading: "Ганзейский союз",
      body: "Пока средиземноморская торговля обогащала Италию, на холодном севере поднималась совсем иная торговая сила — Ганзейский союз. Начиная с XIII века немецкие торговые города во главе с Любеком объединились, чтобы господствовать в торговле на Балтийском и Северном морях. На вершине могущества Союз связывал около 200 городов и держал торговые конторы от Новгорода в России до Бергена, Брюгге и Лондона.\n\nГанза торговала объёмными товарами севера — зерном, лесом, мехами, воском и прежде всего сушёной и солёной рыбой, кормившей католическую Европу в многочисленные постные дни. Ради защиты торговли Союз добивался привилегий, строил склады и даже воевал с королями, угрожавшими ему. Эта купеческая сеть показала, что одна лишь торговля, без единого государя и армии, способна выстроить экономическую империю в полконтинента." },
    mk: { heading: "Ханзеатската лига",
      body: "Додека медитеранската трговија ја збогатуваше Италија, сосема поинаква трговска сила се издигна на студениот север: Ханзеатската лига. Почнувајќи од 13 век, германските трговски градови предводени од Либек се здружија за да доминираат во трговијата на Балтичкото и Северното Море. На својот врв, Лигата поврзуваше околу 200 градови и водеше трговски испостави, или контори, од Новгород во Русија до Берген, Бриж и Лондон.\n\nХанзата тргуваше со масовните стоки на северот — жито, дрво, крзна, восок и пред сè сушена и солена риба што ја хранеше католичка Европа во нејзините многубројни постни денови. За да ја заштити трговијата, Лигата преговараше за привилегии, градеше складишта, па дури и војуваше против кралеви што ѝ се закануваа. Оваа трговска мрежа покажа дека самата трговија, без единствен владетел или војска, може да организира економска империја што опфаќа половина континент." },
    de: { heading: "Die Hanse",
      body: "Während der Mittelmeerhandel Italien bereicherte, erhob sich im kalten Norden eine ganz andere Handelsmacht: die Hanse. Ab dem 13. Jahrhundert schlossen sich deutsche Kaufmannsstädte unter Führung Lübecks zusammen, um den Handel über Ostsee und Nordsee zu beherrschen. Auf ihrem Höhepunkt verband die Hanse etwa 200 Städte und unterhielt Handelsniederlassungen, die Kontore, von Nowgorod in Russland bis Bergen, Brügge und London.\n\nDie Hanse handelte mit den Massengütern des Nordens — Getreide, Holz, Pelzen, Wachs und vor allem getrocknetem und gesalzenem Fisch, der das katholische Europa an seinen vielen Fastentagen ernährte. Zum Schutz ihres Handels handelte die Hanse Privilegien aus, baute Lagerhäuser und führte sogar Krieg gegen Könige, die sie bedrohten. Dieses Kaufmannsnetz zeigte, dass Handel allein, ohne einen einzigen Herrscher oder ein Heer, ein Wirtschaftsimperium über einen halben Kontinent hinweg organisieren konnte." },
    fr: { heading: "La Ligue hanséatique",
      body: "Tandis que le commerce méditerranéen enrichissait l'Italie, une puissance marchande bien différente s'élevait dans le froid Nord : la Ligue hanséatique. À partir du XIIIe siècle, des villes marchandes allemandes menées par Lübeck s'unirent pour dominer le commerce de la Baltique et de la mer du Nord. À son apogée, la Ligue reliait quelque 200 villes et tenait des comptoirs, les kontors, de Novgorod en Russie jusqu'à Bergen, Bruges et Londres.\n\nLa Hanse négociait les marchandises de masse du Nord — grain, bois, fourrures, cire et surtout poisson séché et salé qui nourrissait l'Europe catholique lors de ses nombreux jours de jeûne. Pour protéger son commerce, la Ligue négociait des privilèges, bâtissait des entrepôts et faisait même la guerre aux rois qui la menaçaient. Ce réseau marchand montra que le commerce seul, sans souverain unique ni armée, pouvait organiser un empire économique s'étendant sur un demi-continent." },
  },
  'medieval-05': {
    en: { heading: "The Yam: The Mongols' Pony Express",
      body: "The Mongols ruled the largest contiguous land empire in history, and they held it together with a brilliant relay system called the yam. Every 30 to 60 kilometers along the empire's roads stood a relay station stocked with fresh horses, food, and shelter. A rider bearing an official passport — an inscribed tablet called a paiza — could gallop from one station to the next, hand his message to a fresh rider and mount, and so speed news across thousands of kilometers in days.\n\nThe yam carried imperial orders, tax records, and intelligence, binding the vast realm from China to Persia. It also made long-distance trade and travel safer than ever before, protected by Mongol law. It was along these guarded roads that the merchant Marco Polo journeyed to the court of Kublai Khan, and that goods, technologies, and even the plague would later travel between East and West." },
    es: { heading: "El yam: el correo veloz de los mongoles",
      body: "Los mongoles gobernaron el mayor imperio terrestre continuo de la historia, y lo mantuvieron unido con un brillante sistema de postas llamado yam. Cada 30 a 60 kilómetros, a lo largo de los caminos del imperio, había una estación de relevo provista de caballos frescos, comida y refugio. Un jinete que portara un salvoconducto oficial —una tablilla grabada llamada paiza— podía galopar de una estación a la siguiente, entregar su mensaje a un jinete y una montura de refresco, y así llevar noticias a través de miles de kilómetros en pocos días.\n\nEl yam transportaba órdenes imperiales, registros fiscales e información, ligando el vasto reino desde China hasta Persia. También hizo el comercio y los viajes de larga distancia más seguros que nunca, protegidos por la ley mongola. Fue por estos caminos vigilados por donde el mercader Marco Polo viajó a la corte de Kublai Kan, y por donde más tarde viajarían mercancías, tecnologías e incluso la peste entre Oriente y Occidente." },
    ru: { heading: "Ям: монгольская почта",
      body: "Монголы правили крупнейшей в истории непрерывной сухопутной империей и удерживали её благодаря блестящей системе почтовых станций — яму. Через каждые 30–60 километров вдоль имперских дорог стояла станция со свежими лошадьми, едой и кровом. Гонец с официальной подорожной — дощечкой с надписью, называемой пайцза, — мог мчаться от станции к станции, передавать сообщение свежему всаднику и коню и так проносить вести через тысячи километров за считанные дни.\n\nЯм разносил имперские приказы, податные списки и разведданные, связывая огромную державу от Китая до Персии. Он же сделал дальнюю торговлю и путешествия безопаснее, чем когда-либо, под защитой монгольского закона. Именно по этим охраняемым дорогам купец Марко Поло добрался до двора Хубилай-хана, и по ним же позже потекли между Востоком и Западом товары, технологии и даже чума." },
    mk: { heading: "Јам: монголската брза пошта",
      body: "Монголите владееја со најголемата непрекината копнена империја во историјата и ја држеа заедно со брилијантен систем на станици наречен јам. На секои 30 до 60 километри долж империските патишта стоеше станица за смена, снабдена со свежи коњи, храна и засолниште. Јавач со официјален пропусник — врежана плочка наречена пајца — можеше да галопира од една станица до следната, да ја предаде својата порака на свеж јавач и коњ, и така да пренесе вести преку илјадници километри за неколку дена.\n\nЈамот носеше империски наредби, даночни записи и разузнавачки податоци, поврзувајќи го огромното царство од Кина до Персија. Исто така ја направи трговијата и патувањето на долги растојанија побезбедни од кога било, заштитени со монголскиот закон. Токму по овие чувани патишта трговецот Марко Поло отпатува до дворот на Кублај Кан, и по нив подоцна ќе патуваа стоки, технологии, па дури и чумата меѓу Истокот и Западот." },
    de: { heading: "Das Yam: der Ponyexpress der Mongolen",
      body: "Die Mongolen beherrschten das größte zusammenhängende Landreich der Geschichte und hielten es mit einem genialen Relaissystem namens Yam zusammen. Alle 30 bis 60 Kilometer stand entlang der Reichsstraßen eine Relaisstation mit frischen Pferden, Verpflegung und Unterkunft. Ein Reiter mit amtlichem Passierschein — einer beschrifteten Tafel namens Paiza — konnte von einer Station zur nächsten galoppieren, seine Botschaft einem frischen Reiter und Pferd übergeben und so Nachrichten in wenigen Tagen über tausende Kilometer tragen.\n\nDas Yam beförderte kaiserliche Befehle, Steuerlisten und Nachrichten und band das riesige Reich von China bis Persien zusammen. Es machte auch Fernhandel und Reisen sicherer als je zuvor, geschützt durch mongolisches Recht. Auf diesen bewachten Straßen reiste der Kaufmann Marco Polo an den Hof Kublai Khans, und auf ihnen sollten später Waren, Techniken und selbst die Pest zwischen Ost und West wandern." },
    fr: { heading: "Le yam : le pony express des Mongols",
      body: "Les Mongols régnaient sur le plus vaste empire terrestre d'un seul tenant de l'histoire, et ils le tenaient grâce à un brillant système de relais appelé le yam. Tous les 30 à 60 kilomètres, le long des routes de l'empire, se dressait une station de relais pourvue de chevaux frais, de vivres et d'un abri. Un cavalier muni d'un sauf-conduit officiel — une tablette gravée appelée paiza — pouvait galoper d'une station à l'autre, remettre son message à un cavalier et une monture frais, et ainsi porter des nouvelles à travers des milliers de kilomètres en quelques jours.\n\nLe yam acheminait ordres impériaux, registres fiscaux et renseignements, liant le vaste royaume de la Chine à la Perse. Il rendit aussi le commerce et les voyages au long cours plus sûrs que jamais, protégés par la loi mongole. C'est par ces routes gardées que le marchand Marco Polo gagna la cour de Kubilai Khan, et par elles que voyageraient plus tard marchandises, techniques et jusqu'à la peste entre l'Orient et l'Occident." },
  },
  'medieval-06': {
    en: { heading: "The Divine Wind: Japan Repels the Mongols",
      body: "Twice in the 13th century, the Mongol empire of Kublai Khan launched vast seaborne invasions of Japan, and twice Japan was saved as much by the weather as by the sword. In 1274 a Mongol fleet landed at Hakata Bay but withdrew after fierce samurai resistance and a sudden storm. Warned, the Japanese built a defensive stone wall along the coast.\n\nIn 1281 the Mongols returned with one of the largest naval forces in history — perhaps 4,000 ships and over 100,000 men. The samurai held the wall for weeks until a massive typhoon smashed the anchored Mongol fleet against the shore, drowning tens of thousands. The Japanese called these saving storms kamikaze, the 'divine wind,' and took them as proof that the gods themselves protected Japan — a belief that would echo dangerously into the twentieth century." },
    es: { heading: "El viento divino: Japón rechaza a los mongoles",
      body: "Dos veces en el siglo XIII, el imperio mongol de Kublai Kan lanzó enormes invasiones por mar contra Japón, y dos veces Japón se salvó tanto por el clima como por la espada. En 1274 una flota mongola desembarcó en la bahía de Hakata, pero se retiró tras la feroz resistencia de los samuráis y una tormenta repentina. Advertidos, los japoneses levantaron un muro defensivo de piedra a lo largo de la costa.\n\nEn 1281 los mongoles regresaron con una de las mayores fuerzas navales de la historia: quizá 4.000 barcos y más de 100.000 hombres. Los samuráis defendieron el muro durante semanas hasta que un tifón descomunal estrelló la flota mongola anclada contra la orilla, ahogando a decenas de miles. Los japoneses llamaron a estas tormentas salvadoras kamikaze, el 'viento divino', y las tomaron como prueba de que los propios dioses protegían Japón, una creencia que resonaría peligrosamente hasta el siglo XX." },
    ru: { heading: "Божественный ветер: Япония отражает монголов",
      body: "Дважды в XIII веке монгольская империя Хубилай-хана предпринимала огромные морские вторжения в Японию, и дважды Японию спасала погода не меньше, чем меч. В 1274 году монгольский флот высадился в заливе Хаката, но отступил после яростного сопротивления самураев и внезапной бури. Предупреждённые, японцы возвели вдоль побережья оборонительную каменную стену.\n\nВ 1281 году монголы вернулись с одной из крупнейших морских армий в истории — быть может, 4000 кораблей и более 100 000 человек. Самураи удерживали стену неделями, пока чудовищный тайфун не разбил стоявший на якоре монгольский флот о берег, утопив десятки тысяч. Эти спасительные бури японцы назвали камикадзе — «божественный ветер» — и увидели в них доказательство, что саму Японию хранят боги; вера, которая опасно отзовётся в двадцатом веке." },
    mk: { heading: "Божествениот ветер: Јапонија ги одбива Монголите",
      body: "Двапати во 13 век монголската империја на Кублај Кан започна огромни поморски инвазии врз Јапонија, и двапати Јапонија беше спасена колку од времето, толку и од мечот. Во 1274 година монголска флота се истовари во заливот Хаката, но се повлече по жестокиот отпор на самураите и една ненадејна бура. Предупредени, Јапонците подигнаа одбранбен камен ѕид долж крајбрежјето.\n\nВо 1281 година Монголите се вратија со една од најголемите поморски сили во историјата — можеби 4.000 бродови и над 100.000 луѓе. Самураите го држеа ѕидот со недели сè додека огромен тајфун не ја разби закотвената монголска флота од брегот, давејќи десетици илјади. Јапонците овие спасоносни бури ги нарекоа камиказе, „божествениот ветер“, и ги сфатија како доказ дека самите богови ја штитат Јапонија — верување што опасно ќе одекне и во дваесеттиот век." },
    de: { heading: "Der göttliche Wind: Japan wehrt die Mongolen ab",
      body: "Zweimal im 13. Jahrhundert entsandte das Mongolenreich Kublai Khans gewaltige Seeinvasionen gegen Japan, und zweimal wurde Japan ebenso vom Wetter wie vom Schwert gerettet. 1274 landete eine mongolische Flotte in der Bucht von Hakata, zog sich aber nach erbittertem Widerstand der Samurai und einem plötzlichen Sturm zurück. Gewarnt, errichteten die Japaner eine steinerne Schutzmauer entlang der Küste.\n\n1281 kehrten die Mongolen mit einer der größten Seestreitmächte der Geschichte zurück — vielleicht 4.000 Schiffe und über 100.000 Mann. Die Samurai hielten die Mauer wochenlang, bis ein gewaltiger Taifun die vor Anker liegende mongolische Flotte an die Küste schmetterte und Zehntausende ertränkte. Die Japaner nannten diese rettenden Stürme Kamikaze, den 'göttlichen Wind', und nahmen sie als Beweis, dass die Götter selbst Japan beschützten — ein Glaube, der noch im zwanzigsten Jahrhundert gefährlich nachhallen sollte." },
    fr: { heading: "Le vent divin : le Japon repousse les Mongols",
      body: "Deux fois au XIIIe siècle, l'empire mongol de Kubilai Khan lança d'immenses invasions maritimes contre le Japon, et deux fois le Japon fut sauvé autant par le temps que par l'épée. En 1274, une flotte mongole débarqua dans la baie de Hakata, mais se retira après la farouche résistance des samouraïs et une soudaine tempête. Avertis, les Japonais élevèrent un mur de pierre défensif le long de la côte.\n\nEn 1281, les Mongols revinrent avec l'une des plus grandes forces navales de l'histoire — peut-être 4 000 navires et plus de 100 000 hommes. Les samouraïs tinrent le mur des semaines durant, jusqu'à ce qu'un typhon colossal fracasse la flotte mongole à l'ancre contre le rivage, noyant des dizaines de milliers d'hommes. Les Japonais nommèrent ces tempêtes salvatrices kamikaze, le 'vent divin', et y virent la preuve que les dieux eux-mêmes protégeaient le Japon — une croyance qui résonnerait dangereusement jusqu'au XXe siècle." },
  },
  'medieval-07': {
    en: { heading: "Gods and Sagas: The Norse Imagination",
      body: "The Vikings carried with them a rich pagan religion and a towering body of story. They worshipped a family of gods led by one-eyed Odin, god of war, wisdom, and poetry, and by red-bearded Thor, whose hammer Mjölnir guarded the world against giants. Their cosmos was bound together by the world-tree Yggdrasil and shadowed by the certainty of Ragnarök, the doom in which gods and monsters would destroy one another and the world be reborn.\n\nMuch of what we know survives thanks to Iceland, where settlers preserved and later wrote down the myths and the sagas — vivid prose tales of feuds, voyages, and heroes that stand among the great literature of the Middle Ages. Even as the Norse gradually converted to Christianity after 1000 CE, these stories endured, shaping European imagination down to the names of our days of the week." },
    es: { heading: "Dioses y sagas: la imaginación nórdica",
      body: "Los vikingos llevaban consigo una rica religión pagana y un imponente acervo de relatos. Adoraban a una familia de dioses encabezada por Odín, el tuerto, dios de la guerra, la sabiduría y la poesía, y por Thor, el de la barba roja, cuyo martillo Mjölnir protegía el mundo de los gigantes. Su cosmos estaba unido por el árbol del mundo, Yggdrasil, y ensombrecido por la certeza del Ragnarök, la perdición en la que dioses y monstruos se destruirían mutuamente y el mundo renacería.\n\nGran parte de lo que sabemos sobrevive gracias a Islandia, donde los colonos conservaron y más tarde pusieron por escrito los mitos y las sagas: vívidos relatos en prosa de disputas, viajes y héroes que figuran entre la gran literatura de la Edad Media. Aun cuando los nórdicos se convirtieron poco a poco al cristianismo después del año 1000, estas historias perduraron, moldeando la imaginación europea hasta en los nombres de nuestros días de la semana." },
    ru: { heading: "Боги и саги: воображение северян",
      body: "Викинги несли с собой богатую языческую религию и грандиозный свод преданий. Они почитали семью богов во главе с одноглазым Одином, богом войны, мудрости и поэзии, и рыжебородым Тором, чей молот Мьёльнир хранил мир от великанов. Их мироздание держалось на мировом древе Иггдрасиль и было омрачено неизбежностью Рагнарёка — гибели, в которой боги и чудовища истребят друг друга, а мир возродится.\n\nМногое из того, что мы знаем, уцелело благодаря Исландии, где поселенцы сберегли, а позже записали мифы и саги — яркие прозаические повести о распрях, плаваниях и героях, стоящие среди великой литературы Средневековья. Даже когда северяне после 1000 года постепенно приняли христианство, эти истории уцелели, формируя европейское воображение вплоть до названий наших дней недели." },
    mk: { heading: "Богови и саги: нордиската имагинација",
      body: "Викинзите носеа со себе богата паганска религија и величествен корпус приказни. Обожаваа семејство богови предводено од еднооокиот Один, богот на војната, мудроста и поезијата, и од црвенобрадиот Тор, чиј чекан Мјолнир го чуваше светот од џиновите. Нивниот космос беше сврзан со светското дрво Игдрасил и засенет од извесноста на Рагнарок — пропаста во која боговите и чудовиштата ќе се уништат меѓусебно, а светот ќе се прероди.\n\nМногу од она што го знаеме преживеало благодарение на Исланд, каде што доселениците ги зачувале, а подоцна ги запишале митовите и сагите — живописни прозни приказни за крвни одмазди, патувања и херои што спаѓаат меѓу големата литература на Средниот век. Дури и додека нордијците постепено се преобратуваа во христијанство по 1000 година, овие приказни опстанаа, обликувајќи ја европската имагинација сè до имињата на деновите во неделата." },
    de: { heading: "Götter und Sagas: die nordische Vorstellungswelt",
      body: "Die Wikinger trugen eine reiche heidnische Religion und einen gewaltigen Schatz an Erzählungen mit sich. Sie verehrten eine Götterfamilie unter dem einäugigen Odin, dem Gott des Krieges, der Weisheit und der Dichtkunst, und dem rotbärtigen Thor, dessen Hammer Mjölnir die Welt vor den Riesen schützte. Ihr Kosmos wurde vom Weltenbaum Yggdrasil zusammengehalten und von der Gewissheit des Ragnarök überschattet — dem Untergang, in dem Götter und Ungeheuer einander vernichten und die Welt neu geboren wird.\n\nVieles von dem, was wir wissen, überlebte dank Island, wo Siedler die Mythen und Sagas bewahrten und später niederschrieben — lebendige Prosaerzählungen von Fehden, Fahrten und Helden, die zur großen Literatur des Mittelalters zählen. Auch als die Nordleute sich nach 1000 allmählich zum Christentum bekehrten, überdauerten diese Geschichten und prägten die europäische Vorstellungswelt bis hinein in die Namen unserer Wochentage." },
    fr: { heading: "Dieux et sagas : l'imaginaire nordique",
      body: "Les Vikings portaient avec eux une riche religion païenne et un immense corpus de récits. Ils vénéraient une famille de dieux menée par Odin le borgne, dieu de la guerre, de la sagesse et de la poésie, et par Thor à la barbe rousse, dont le marteau Mjöllnir protégeait le monde des géants. Leur cosmos était tenu par l'arbre-monde Yggdrasil et assombri par la certitude du Ragnarök, la fin où dieux et monstres se détruiraient et où le monde renaîtrait.\n\nUne grande part de ce que nous savons a survécu grâce à l'Islande, où les colons préservèrent puis mirent par écrit les mythes et les sagas — de vivants récits en prose de querelles, de voyages et de héros qui comptent parmi la grande littérature du Moyen Âge. Même lorsque les Scandinaves se convertirent peu à peu au christianisme après l'an 1000, ces récits perdurèrent, façonnant l'imaginaire européen jusque dans les noms de nos jours de la semaine." },
  },
  'medieval-08': {
    en: { heading: "Convivencia: Three Faiths in Iberia",
      body: "For much of the Middle Ages, Islamic Spain was the most sophisticated society in Western Europe, and its cities became a meeting place for three faiths. Under Muslim rule, Córdoba grew into one of the world's great cities, with paved and lamp-lit streets, running water, libraries, and hundreds of thousands of books at a time when most European towns were small and dark. Muslims, Christians, and Jews lived side by side in an often-fragile coexistence later called la convivencia.\n\nThis mingling made Iberia a bridge for knowledge. In cities like Toledo, teams of Muslim, Jewish, and Christian scholars translated Arabic and Greek works — Aristotle, medicine, astronomy, and mathematics — into Latin. Thinkers such as the Muslim philosopher Averroes and the Jewish sage Maimonides shaped European thought for centuries. Through Spain, the learning of the ancient and Islamic worlds flowed north to spark the revival of European universities." },
    es: { heading: "La convivencia: tres religiones en Iberia",
      body: "Durante buena parte de la Edad Media, la España islámica fue la sociedad más avanzada de Europa occidental, y sus ciudades se volvieron lugar de encuentro de tres religiones. Bajo el dominio musulmán, Córdoba llegó a ser una de las grandes ciudades del mundo, con calles pavimentadas e iluminadas, agua corriente, bibliotecas y cientos de miles de libros en una época en que la mayoría de las villas europeas eran pequeñas y oscuras. Musulmanes, cristianos y judíos vivían codo con codo en una coexistencia a menudo frágil, llamada más tarde la convivencia.\n\nEsa mezcla hizo de Iberia un puente para el saber. En ciudades como Toledo, equipos de sabios musulmanes, judíos y cristianos tradujeron al latín obras árabes y griegas —Aristóteles, medicina, astronomía y matemáticas—. Pensadores como el filósofo musulmán Averroes y el sabio judío Maimónides moldearon el pensamiento europeo durante siglos. A través de España, el saber de los mundos antiguo e islámico fluyó hacia el norte y encendió el renacer de las universidades europeas." },
    ru: { heading: "Конвивенсия: три веры на Пиренеях",
      body: "Значительную часть Средневековья исламская Испания была самым развитым обществом Западной Европы, а её города стали местом встречи трёх вер. Под властью мусульман Кордова выросла в один из величайших городов мира — с мощёными и освещёнными улицами, водопроводом, библиотеками и сотнями тысяч книг в то время, когда большинство европейских городков были малы и темны. Мусульмане, христиане и иудеи жили бок о бок в зачастую хрупком сосуществовании, позже названном la convivencia.\n\nЭто смешение сделало Пиренеи мостом для знаний. В таких городах, как Толедо, коллективы мусульманских, иудейских и христианских учёных переводили на латынь арабские и греческие труды — Аристотеля, медицину, астрономию и математику. Мыслители вроде мусульманского философа Аверроэса и иудейского мудреца Маймонида веками формировали европейскую мысль. Через Испанию учёность античного и исламского миров текла на север, разжигая возрождение европейских университетов." },
    mk: { heading: "Конвивенсија: три вери на Пиринејскиот Полуостров",
      body: "Голем дел од Средниот век, исламска Шпанија беше најнапредното општество во Западна Европа, а нејзините градови станаа место на средба на три вери. Под муслиманска власт, Кордоба прерасна во еден од најголемите градови во светот — со поплочени и осветлени улици, водовод, библиотеки и стотици илјади книги во време кога повеќето европски градчиња беа мали и темни. Муслиманите, христијаните и Евреите живееја рамо до рамо во често кревко сожителство, подоцна наречено la convivencia.\n\nТоа мешање го направи Полуостровот мост за знаењето. Во градови како Толедо, екипи муслимански, еврејски и христијански учени преведуваа на латински арапски и грчки дела — Аристотел, медицина, астрономија и математика. Мислители како муслиманскиот филозоф Авероес (Ибн Рушд) и еврејскиот мудрец Мајмонид го обликуваа европското мислење со векови. Преку Шпанија, знаењето на античкиот и исламскиот свет течеше на север и ја запали преродбата на европските универзитети." },
    de: { heading: "Convivencia: drei Glaubensrichtungen in Iberien",
      body: "Über weite Teile des Mittelalters war das islamische Spanien die höchstentwickelte Gesellschaft Westeuropas, und seine Städte wurden zum Treffpunkt dreier Glaubensrichtungen. Unter muslimischer Herrschaft wuchs Córdoba zu einer der großen Städte der Welt heran — mit gepflasterten und beleuchteten Straßen, fließendem Wasser, Bibliotheken und Hunderttausenden von Büchern, zu einer Zeit, als die meisten europäischen Städte klein und dunkel waren. Muslime, Christen und Juden lebten Seite an Seite in einem oft brüchigen Zusammenleben, das später la convivencia genannt wurde.\n\nDiese Vermischung machte Iberien zu einer Brücke des Wissens. In Städten wie Toledo übersetzten Teams muslimischer, jüdischer und christlicher Gelehrter arabische und griechische Werke — Aristoteles, Medizin, Astronomie und Mathematik — ins Lateinische. Denker wie der muslimische Philosoph Averroes und der jüdische Weise Maimonides prägten das europäische Denken über Jahrhunderte. Über Spanien floss das Wissen der antiken und der islamischen Welt nach Norden und entfachte die Wiederbelebung der europäischen Universitäten." },
    fr: { heading: "La convivencia : trois confessions en Ibérie",
      body: "Pendant une grande partie du Moyen Âge, l'Espagne islamique fut la société la plus raffinée d'Europe occidentale, et ses villes devinrent un lieu de rencontre de trois confessions. Sous domination musulmane, Cordoue devint l'une des grandes villes du monde — rues pavées et éclairées, eau courante, bibliothèques et des centaines de milliers de livres, à une époque où la plupart des villes européennes étaient petites et obscures. Musulmans, chrétiens et juifs vivaient côte à côte dans une coexistence souvent fragile, plus tard appelée la convivencia.\n\nCe mélange fit de l'Ibérie un pont pour le savoir. Dans des villes comme Tolède, des équipes de savants musulmans, juifs et chrétiens traduisirent en latin des œuvres arabes et grecques — Aristote, la médecine, l'astronomie et les mathématiques. Des penseurs comme le philosophe musulman Averroès et le sage juif Maïmonide façonnèrent la pensée européenne pendant des siècles. Par l'Espagne, le savoir des mondes antique et islamique s'écoula vers le nord et alluma le renouveau des universités européennes." },
  },
  'medieval-09': {
    en: { heading: "The Longbow and the Twilight of the Knight",
      body: "The Hundred Years' War between England and France became a graveyard for the age of mounted chivalry. At Crécy in 1346 and again at Agincourt in 1415, outnumbered English armies destroyed the flower of French knighthood — not with knights of their own, but with massed common archers wielding the longbow. A trained archer could loose ten or more arrows a minute, and clouds of them brought down horses and men before they could close.\n\nThe lesson was brutal and clear: a wall of disciplined commoners could shatter the mounted elite who had dominated European warfare for centuries. As the war dragged on, gunpowder artillery joined the longbow in making castles and armored knights obsolete. Out of this long, grinding conflict the modern nations of England and France were forged — and with them a new kind of warfare in which numbers, discipline, and technology mattered more than noble birth." },
    es: { heading: "El arco largo y el ocaso del caballero",
      body: "La Guerra de los Cien Años entre Inglaterra y Francia se convirtió en el cementerio de la era de la caballería montada. En Crécy en 1346 y de nuevo en Agincourt en 1415, ejércitos ingleses en inferioridad numérica destruyeron la flor de la caballería francesa, no con caballeros propios, sino con masas de arqueros plebeyos armados con el arco largo. Un arquero adiestrado podía disparar diez o más flechas por minuto, y nubes de ellas derribaban caballos y hombres antes de que pudieran acercarse.\n\nLa lección fue brutal y clara: un muro de plebeyos disciplinados podía destrozar a la élite montada que había dominado la guerra europea durante siglos. A medida que la guerra se prolongaba, la artillería de pólvora se sumó al arco largo para volver obsoletos los castillos y los caballeros con armadura. De este conflicto largo y desgastador nacieron las naciones modernas de Inglaterra y Francia, y con ellas una nueva forma de guerra en la que el número, la disciplina y la tecnología importaban más que la cuna noble." },
    ru: { heading: "Длинный лук и закат рыцарства",
      body: "Столетняя война между Англией и Францией стала могилой эпохи конного рыцарства. При Креси в 1346 году и вновь при Азенкуре в 1415-м уступавшие в числе английские армии истребляли цвет французского рыцарства — не своими рыцарями, а массами простых лучников с длинными луками. Обученный лучник мог выпускать десять и более стрел в минуту, и их тучи валили коней и людей прежде, чем те успевали сблизиться.\n\nУрок был жесток и ясен: стена дисциплинированных простолюдинов способна сокрушить конную знать, веками господствовавшую в европейской войне. По мере того как война тянулась, к длинному луку присоединилась пороховая артиллерия, делая замки и латников устаревшими. Из этого долгого, изматывающего противостояния выковались современные нации Англии и Франции — а с ними и новый вид войны, где число, дисциплина и техника значили больше знатного рождения." },
    mk: { heading: "Долгиот лак и самракот на витезот",
      body: "Стогодишната војна меѓу Англија и Франција стана гробница на ерата на коњаничкото витештво. Кај Креси во 1346 година и повторно кај Аженкур во 1415 година, бројчано послабите англиски војски го уништија цветот на француското витештво — не со свои витези, туку со маси обични стрелци вооружени со долгиот лак. Извежбан стрелец можеше да испука десет или повеќе стрели во минута, и облаци од нив соборуваа коњи и луѓе пред тие да успеат да се доближат.\n\nПоуката беше сурова и јасна: ѕид од дисциплинирани простолуѓе можеше да ја скрши коњаничката елита што со векови доминираше во европската војна. Како што војната се влечеше, барутната артилерија му се придружи на долгиот лак правејќи ги замоците и оклопените витези застарени. Од овој долг, исцрпувачки судир се исковаа модерните нации на Англија и Франција — а со нив и нов вид војна во која бројот, дисциплината и технологијата значеа повеќе од благородничкото потекло." },
    de: { heading: "Der Langbogen und die Dämmerung des Ritters",
      body: "Der Hundertjährige Krieg zwischen England und Frankreich wurde zum Grab des Zeitalters des berittenen Rittertums. Bei Crécy 1346 und erneut bei Azincourt 1415 vernichteten zahlenmäßig unterlegene englische Heere die Blüte des französischen Rittertums — nicht mit eigenen Rittern, sondern mit Massen gemeiner Bogenschützen, die den Langbogen führten. Ein geübter Schütze konnte zehn oder mehr Pfeile pro Minute abschießen, und ihre Wolken streckten Pferde und Männer nieder, ehe diese herankamen.\n\nDie Lehre war brutal und klar: eine Wand disziplinierter Gemeiner konnte die berittene Elite zerschlagen, die die europäische Kriegführung jahrhundertelang beherrscht hatte. Während sich der Krieg hinzog, gesellte sich die Pulverartillerie zum Langbogen und machte Burgen und geharnischte Ritter überflüssig. Aus diesem langen, zermürbenden Konflikt wurden die modernen Nationen England und Frankreich geschmiedet — und mit ihnen eine neue Art der Kriegführung, in der Zahl, Disziplin und Technik mehr zählten als edle Geburt." },
    fr: { heading: "L'arc long et le crépuscule du chevalier",
      body: "La guerre de Cent Ans entre l'Angleterre et la France devint le tombeau de l'âge de la chevalerie montée. À Crécy en 1346 et de nouveau à Azincourt en 1415, des armées anglaises en infériorité numérique détruisirent la fleur de la chevalerie française — non avec leurs propres chevaliers, mais avec des masses d'archers roturiers maniant l'arc long. Un archer entraîné pouvait décocher dix flèches ou plus par minute, et leurs nuées abattaient chevaux et hommes avant qu'ils ne pussent joindre.\n\nLa leçon fut brutale et claire : un mur de roturiers disciplinés pouvait briser l'élite montée qui dominait la guerre européenne depuis des siècles. À mesure que la guerre s'éternisait, l'artillerie à poudre rejoignit l'arc long pour rendre châteaux et chevaliers en armure obsolètes. De ce long conflit épuisant furent forgées les nations modernes d'Angleterre et de France — et avec elles une nouvelle forme de guerre où le nombre, la discipline et la technique comptaient plus que la naissance noble." },
  },
};
